            return u.indexOf('#isVideo=true#') >= 0 ? u : (u + '#isVideo=true#');
        }
        let p = this.playProxyUrl(u);
        p = String(p).replace(/;\{[^}]*\}$/, '').replace(/#isVideo=true#/g, '').trim();
        return p + '#isVideo=true#';
    },
    strong: function(txt, color) {
        return '‘‘’’<strong><font color=#' + (color || 'FF6699') + '>' + txt + '</font></strong>';
    },
    fmtDate: function(v) {
        if (!v) return '';
        let s = String(v).replace('T', ' ');
        return s.length > 19 ? s.slice(0, 19) : s;
    },
    fmtDuration: function(sec) {
        sec = parseInt(sec || 0);
        if (!(sec > 0)) return '';
        let h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = sec % 60;
        if (h > 0) return h + ':' + String(m).padStart(2,'0') + ':' + String(s).padStart(2,'0');
        return String(m).padStart(2,'0') + ':' + String(s).padStart(2,'0');
    },
    readList: function(key) {
        try {
            let v = getItem(key, '[]');
            let a = JSON.parse(v || '[]');
            return Array.isArray(a) ? a : [];
        } catch(e) { return []; }
    },
    writeList: function(key, list) {
        try { setItem(key, JSON.stringify(list || [])); } catch(e) {}
    },
    historyKey: 'mdai_watch_history_v1',
    favKey: 'mdai_favorites_v1',
    searchKey: 'mdai_search_history_v1',
    saveHistory: function(info) {
        info = info || {};
        if (!info.id) return;
        let a = this.readList(this.historyKey);
        a = a.filter(x => !(String(x.id) === String(info.id) && String(x.type) === String(info.type)));
        info.time = new Date().getTime();
        a.unshift(info);
        if (a.length > 80) a = a.slice(0,80);
        this.writeList(this.historyKey, a);
    },
    saveSearchWord: function(word) {
        word = String(word || '').trim();
        if (!word) return;
        let a = this.readList(this.searchKey).filter(x => String(x) !== word);
        a.unshift(word);
        if (a.length > 12) a = a.slice(0,12);
        this.writeList(this.searchKey, a);
    },
    isFav: function(id, type) {
        return this.readList(this.favKey).some(x => String(x.id) === String(id) && String(x.type) === String(type));
    },
    toggleFav: function(info) {
        info = info || {};
        let a = this.readList(this.favKey);
        let idx = a.findIndex(x => String(x.id) === String(info.id) && String(x.type) === String(info.type));
        if (idx >= 0) {
            a.splice(idx,1); this.writeList(this.favKey,a); return false;
        }
        info.time = new Date().getTime();
        a.unshift(info);
        this.writeList(this.favKey,a);
        return true;
    },
    sectionTitle: function(title, sub) {
        title=this.maskText(title); sub=this.maskText(sub);
        let t = '““””<b><span style="color:#7C6CFF;font-size:17px">▌ ' + title + '</span></b>';
        if (sub) t += '  <small><font color=#8A8A96>' + sub + '</font></small>';
