var LJ=(function(){
var HOST='https://www.luojubk.xyz';
var UA='Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36';
var REF=HOST+'/';

function safe(s){return String(s==null?'':s)}
function clean(s){return safe(s).replace(/\s+/g,' ').trim()}
function unesc(s){return safe(s)
  .replace(/&#x([0-9a-fA-F]+);/g,function(m,h){return String.fromCharCode(parseInt(h,16))})
  .replace(/&#(\d+);/g,function(m,d){return String.fromCharCode(parseInt(d,10))})
  .replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#34;/g,'"').replace(/&apos;/g,"'").replace(/&#39;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>')}
function stripTags(s){return safe(s).replace(/<[^>]*>/g,'')}
function abs(u){u=safe(u);if(!u)return '';if(/^https?:/i.test(u))return u;if(u.indexOf('//')===0)return 'https:'+u;if(u.charAt(0)==='/')return HOST+u;return HOST+'/'+u}
function enc(s){return encodeURIComponent(safe(s))}
/* 短 hash：用于生成唯一页面 key */
function h32(s){var h=5381,i=0;s=safe(s);while(i<s.length){h=((h*33)+s.charCodeAt(i++))|0}return (h>>>0).toString(36)}

/* base64 壳页面解码 */
function b64shell(html){
  var s=safe(html);
  var m=s.match(/var _s = "([^"]+)"/);
  if(m){try{return base64Decode(m[1])}catch(e){return s}}
  return s;
}

/* 带 Referer 的 GET */
function get(url,opt){
  opt=opt||{};
  var h=opt.headers||{};
  if(!h['Referer'])h['Referer']=REF;
  if(!h['User-Agent'])h['User-Agent']=UA;
  try{return fetch(url,{headers:h,timeout:20000})}catch(e){return ''}
}

/* 磁力二进制解码 */
function reurl(bin){
  var out='',i;
  var chunks=safe(bin).match(/.{1,8}/g)||[];
  for(i=0;i<chunks.length-1;i++){out+=String.fromCharCode(parseInt(chunks[i],2)-10)}
  return out;
}

/* ===== 列表解析：post-item（首页/分类/资源站） ===== */
function parsePostList(html){
  var d=[],blocks=safe(html).split(/<div class="post-item/).slice(1),i;
  for(i=0;i<blocks.length;i++){
    var blk=blocks[i];
    var link=(blk.match(/<a href="(\/news\/[0-9]+\.html)"/)||[])[1];
    if(!link)continue;
    var img=(blk.match(/data-src="([^"]+)"/)||[])[1];
    var title=(blk.match(/<h3 class="post-title">\s*<a[^>]*>([^<]*)<\/a>/)||[])[1]||(blk.match(/alt="([^"]*)"/)||[])[1];
    var date=(blk.match(/<span>(\d{4}-\d{2}-\d{2}|\d{2}-\d{2})<\/span>/)||[])[1];
    var views=(blk.match(/eye-views">[\s\S]*?(\d+)\s*<\/span>/)||[])[1];
    var vips=blk.indexOf('is-vip-card')>=0;
    var item={url:link,img:abs(img),title:clean(unesc(title||'')),date:date||'',views:views||''};
    if(vips)item.vip=1;
    d.push(item);
  }
  return d;
}

/* ===== 搜索解析：v-card ===== */
function parseSearchList(html){
  var d=[],re=/<a href="([^"]+)"\s+class="v-card[^"]*"[^>]*>([\s\S]*?)<\/a>/g,m;
  while((m=re.exec(safe(html)))){
    var url=m[1],blk=m[2];
    var img=(blk.match(/data-src="([^"]+)"/)||[])[1];
    var t=(blk.match(/<h3 class="v-title">([\s\S]*?)<\/h3>/)||[])[1]||'';
    var title=clean(unesc(stripTags(t)));
    var date=(blk.match(/<span>(\d{4}-\d{2}-\d{2})<\/span>/)||[])[1]||'';
    var vips=blk.indexOf('badge-vip')>=0||url.indexOf('/vip/')===0;
    var item={url:url,img:abs(img),title:title,date:date};
    if(vips)item.vip=1;
    d.push(item);
  }
  return d;
}

/* ===== 详情解析 ===== */
function parseDetail(html){
  var s=safe(html);
  var title=clean(unesc((s.match(/<h1 class="v-title-top">([^<]*)/)||[])[1]||''));
  var poster=abs((s.match(/poster="([^"]+)"/)||[])[1]||'');
  var m3u8=(s.match(/data-raw="([^"]+)"/)||[])[1]||'';
  var lines=[],re=/<button[^>]*class="line-btn[^"]*"[^>]*data-type="([^"]*)"[^>]*data-raw="([^"]+)"[^>]*data-cdn="([^"]*)"/g,m;
  while((m=re.exec(s))){
    lines.push({type:m[1],raw:m[2],cdn:m[3]});
  }
  if(!lines.length&&m3u8)lines.push({type:'default',raw:m3u8,cdn:''});
  var date=clean((s.match(/v-meta-item">([\d-]+\s[\d:]*)</)||[])[1]||'');
  var views=clean((s.match(/v-meta-item">[\s\S]{0,200}?(\d+)\s*<\/span>/)||[])[1]||'');
  var cat=clean(unesc((s.match(/v-cat-link">([^<]*)</)||[])[1]||''));
  var feedback=(s.match(/data-m3u8="([^"]+)"/)||[])[1]||'';
  return {title:title,poster:poster,m3u8:m3u8,lines:lines,date:date,views:views,cat:cat,feedback:feedback};
}

/* ===== 磁力列表解析（cili-list） ===== */
function parseCiliList(html){
  var d=[],blocks=safe(html).split(/<div class="post-item/).slice(1),i;
  for(i=0;i<blocks.length;i++){
    var blk=blocks[i];
    var link=(blk.match(/<a href="(\/cili-detail\/[0-9]+\.html)"/)||[])[1];
    if(!link)continue;
    var img=(blk.match(/data-src="([^"]+)"/)||[])[1];
    var title=(blk.match(/<h3 class="post-title">\s*<a[^>]*>([^<]*)<\/a>/)||[])[1]||'';
    var date=(blk.match(/<span>(\d{4}-\d{2}-\d{2})<\/span>/)||[])[1];
    d.push({url:link,img:abs(img),title:clean(unesc(title)),date:date||''});
  }
  return d;
}

/* ===== 磁力详情解析 ===== */
function parseCiliDetail(html){
  var s=safe(html);
  var title=clean(unesc((s.match(/<h1[^>]*>([^<]*)</)||[])[1]||''));
  var cover=abs((s.match(/data-src="([^"]+)"/)||[])[1]||'');
  var magnets=[],re=/reurl\('([01]+)'\)/g,m;
  var seen={};
  while((m=re.exec(s))){
    var h=reurl(m[1]);
    if(h&&!seen[h]){seen[h]=1;magnets.push(h)}
  }
  var names=[],rn=/<span class="name">([^<]*)<\/span>/g;
  while((m=rn.exec(s))){names.push(clean(m[1]))}
  var metas=[],rm=/<span class="meta">([^<]*)<\/span>/g;
  while((m=rm.exec(s))){metas.push(clean(m[1]))}
  return {title:title,cover:cover,magnets:magnets,names:names,metas:metas};
}

/* ===== 美图列表解析（feed-item） ===== */
function parseMeituList(html){
  var d=[],blocks=safe(html).split(/<div class="feed-item">/).slice(1),i;
  for(i=0;i<blocks.length;i++){
    var blk=blocks[i];
    var link=(blk.match(/<a href="(\/meitu\/[0-9]+\.html)"/)||[])[1];
    if(!link)continue;
    var title=(blk.match(/<h2 class="feed-title">\s*<a[^>]*>([^<]*)<\/a>/)||[])[1]||'';
    var imgs=[],ri=/data-src="([^"]+)"/g,mm;
    while((mm=ri.exec(blk))){imgs.push(abs(mm[1]));if(imgs.length>=6)break}
    d.push({url:link,img:imgs[0]||'',title:clean(unesc(title)),imgs:imgs});
