}

/* ===== 美图详情解析 ===== */
function parseMeituDetail(html){
  var s=safe(html);
  var title=clean(unesc((s.match(/<title>([^<]*)/)||[])[1]||'').replace(/\s*-\s*美图馆.*$/,''));
