/* ===== VIP 自动登录引擎 v3：XFF 无限注册 =====
   核心突破：注册接口的 IP 限流可通过 X-Forwarded-For 头绕过（实测 5/5 成功）。
   策略：每账号每日 2 次试看 → 配额耗尽时用随机 XFF 注册新账号 → 无限循环。
   持久化：lj_vip_pool = [{u,p}], lj_vip_used = {视频id:1} 已看记录 */

function vipGenUser(){
  return 'lj'+Date.now().toString(36)+Math.random().toString(36).slice(2,6);
}

/* 随机 XFF IP（用于绕过注册限流） */
function vipRandIP(){
  var a=Math.floor(Math.random()*200)+20;
  var b=Math.floor(Math.random()*255);
  var c=Math.floor(Math.random()*255);
  var d=Math.floor(Math.random()*254)+1;
  return a+'.'+b+'.'+c+'.'+d;
}

function vipGetPool(){
  try{
    var s=getItem('lj_vip_pool','');
    if(s){var a=JSON.parse(s);if(a&&a.length)return a}
  }catch(e){}
  var old=getItem('lj_vip_acc','');
  if(old){
    try{var o=JSON.parse(old);if(o.u)return [{u:o.u,p:o.p}]}catch(e){}
  }
  return [];
}

function vipSavePool(pool){
  try{setItem('lj_vip_pool',JSON.stringify(pool.slice(0,12)))}catch(e){}
}

/* 注册新账号（带随机 XFF 绕过限流） */
function vipRegister(){
  var u=vipGenUser(), p='LJ'+Math.random().toString(36).slice(2,10);
  try{
    var resp=String(fetch(C.HOST+'/vip/login/api_register.php',{
      method:'POST',
      headers:{'Content-Type':'application/json','X-Forwarded-For':vipRandIP()},
      body:JSON.stringify({username:u,password:p}),
      timeout:20000
    }));
    if(resp.indexOf('code')>=0&&resp.indexOf('200')>=0&&resp.indexOf('403')<0){
      return {u:u,p:p};
    }
  }catch(e){}
  return null;
}

function vipLoginAcc(u,p){
  try{
    var resp=String(fetch(C.HOST+'/vip/login/api_login.php',{
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({username:u,password:p}),
      timeout:20000
    }));
    return resp.indexOf('code')>=0&&resp.indexOf('200')>=0&&resp.indexOf('401')<0&&resp.indexOf('403')<0;
  }catch(e){return false}
}

function vipTryFetch(id){
  try{
    var html=C.b64shell(String(fetch(C.HOST+'/vip/play.php?id='+id,{
      headers:{'Referer':C.REF},
      timeout:20000
    })));
    var m=html.match(/data-raw="([^"]+)"/);
    if(m)return {url:m[1]};
    if(html.indexOf('次数已用完')>=0)return {lock:'quota'};
    if(html.indexOf('vip-lock-content')>=0)return {lock:'login'};
    return {lock:'unknown'};
  }catch(e){return {lock:'error'}}
}

/* 主入口：当前会话 → 池内轮换 → XFF 无限注册 */
function vipGetPlay(id){
  id=String(id||'');
  if(!id)return {lock:'badid'};
  /* 1. 当前会话 */
  var r1=vipTryFetch(id);
  if(r1.url)return r1;
  var sawQuota=(r1.lock==='quota');
  /* 2. 池内账号轮换 */
  var pool=vipGetPool();
  for(var i=0;i<pool.length;i++){
    var acc=pool[i];
    if(!acc.u)continue;
    if(vipLoginAcc(acc.u,acc.p)){
      var r2=vipTryFetch(id);
      if(r2.url){
        pool.splice(i,1);
        pool.unshift(acc);
        vipSavePool(pool);
        return r2;
      }
      if(r2.lock==='quota'){sawQuota=true;continue}
    }
  }
  /* 3. XFF 无限注册（最多尝试 3 次） */
  for(var k=0;k<3;k++){
    var na=vipRegister();
    if(!na)break;
    if(vipLoginAcc(na.u,na.p)){
      var r3=vipTryFetch(id);
      pool.unshift({u:na.u,p:na.p});
      vipSavePool(pool);
      if(r3.url)return r3;
      if(r3.lock==='quota'){sawQuota=true;continue}
    }
  }
  return sawQuota?{lock:'quota'}:{lock:'fail'};
}
