    {k:'paihang', n:'热播', path:'/paihang/'},
    {k:'biaoqian', n:'标签', path:'/biaoqian/'}
  ],

  colors: [
    {bg:'#FFE4EC', fg:'#C2185B'},
    {bg:'#E3F2FD', fg:'#1565C0'},
    {bg:'#F3E5F5', fg:'#7B1FA2'},
    {bg:'#E8F5E9', fg:'#2E7D32'},
    {bg:'#FFF3E0', fg:'#E65100'},
    {bg:'#E0F7FA', fg:'#00838F'},
    {bg:'#FCE4EC', fg:'#AD1457'},
    {bg:'#EDE7F6', fg:'#4527A0'},
    {bg:'#FFF8E1', fg:'#F57F17'}
  ],

  get: function(url){
    var html = fetch(url, {
      headers: {
        'User-Agent': this.ua,
        'Accept': 'text/html,application/xhtml+xml',
        'Referer': this.host + '/'
      }
    });
    return html || '';
  },

  abs: function(u){
    if(!u) return '';
    if(u.indexOf('http')===0) return u;
    if(u.charAt(0)==='/') return this.host + u;
    return this.host + '/' + u;
  },

  colorAt: function(i){ return this.colors[i % this.colors.length]; },

  imageJs: '',

  // 91crdj 的封面是 AES/CBC/NoPadding 密文，网页端由 crypto-worker 解密。
  imageDec: function(url){
    if(!url) return '';
    if(!this.imageJs){
      this.imageJs = $.toString(function(){
        var javaImport = new JavaImporter();
        javaImport.importPackage(
          Packages.com.example.hikerview.utils,
          Packages.java.lang,
          Packages.javax.crypto,
          Packages.javax.crypto.spec
        );
        with(javaImport){
          var bytes = FileUtil.toBytes(input);
          var key = new java.lang.String('f5d965df75336270').getBytes('UTF-8');
          var iv = new java.lang.String('97b60394abc2fbe1').getBytes('UTF-8');
          var cipher = Cipher.getInstance('AES/CBC/NoPadding');
          cipher.init(2, new SecretKeySpec(key, 'AES'), new IvParameterSpec(iv));
          return FileUtil.toInputStream(cipher.doFinal(bytes));
        }
      });
    }
    return url + '@js=' + this.imageJs;
  },

  decode: function(s){
    if(!s) return '';
    return (''+s)
      .replace(/\\u0026/g,'&')
      .replace(/&amp;/g,'&')
      .replace(/&lt;/g,'<')
      .replace(/&gt;/g,'>')
      .replace(/&quot;/g,'"')
      .replace(/&#34;/g,'"')
      .replace(/&#39;/g,"'")
      .replace(/\\\//g,'/');
  },

  // 卡片：只用 img 的 src=（避开 data-preview-src）
  parseCards: function(html){
    var list = [], seen = {};
    if(!html) return list;
    // 整块卡片：懒加载真实图在 data-src
    var re = /<a class="card" href="([^"]+)"([^>]*)>([\s\S]*?)<\/a>/g;
    var m;
    while((m = re.exec(html))){
      var url = m[1];
      if(seen[url]) continue;
      var block = m[3] || '';
      if(block.indexOf('p-img') < 0 && block.indexOf('poster') < 0) continue;
      seen[url] = 1;
      var attrs = m[2] || '';
      var nm = attrs.match(/data-track-item-name="([^"]*)"/);
      var title = nm ? this.decode(nm[1]) : '';
      if(!title){
        var h3 = block.match(/<h3>([^<]+)<\/h3>/);
        if(h3) title = this.decode(h3[1]);
      }
      var img = '';
      var ds = block.match(/data-src="(https?:\/\/[^"]+)"/);
      if(ds) img = ds[1];
      if(!img){
        var sm = block.match(/\ssrc="(https?:\/\/[^"]+)"/);
        if(sm && !/\.m3u8/i.test(sm[1]) && sm[1].indexOf('data:') !== 0) img = sm[1];
      }
      // 站点自有海报兜底
      if(!img){
        var idm = attrs.match(/data-track-item-id="([^"]+)"/);
        var typ = attrs.match(/data-track-item-type="([^"]+)"/);
        if(idm){
          var t = (typ && typ[1] === 'comic') ? 'comic' : (typ && typ[1] === 'novel') ? 'novel' : 'video';
          img = this.host + '/media/posters/' + t + '/' + idm[1];
        }
      }
      if(img) img = this.decode(img);
      if(/\.m3u8/i.test(img) || (img && img.indexOf('data:') === 0)) img = '';
      list.push({ url: url, title: title || '作品', img: this.abs(img) });
    }
    return list;
  },

  // 首页按分区取卡片并去重（官方推荐 / 热播 / 各栏目）
  parseHome: function(html){
