  novel: function(){
    var d = [], url = '', title = '';
    try{ url = getMyVar('crdj_novel_url', '') || ''; }catch(e){}
    try{ title = getMyVar('crdj_novel_title', '') || ''; }catch(e){}
    if(title) d.push({ title: title, url: 'hiker://empty', col_type: 'text_1' });
    if(!url){
      d.push({ title: '无内容', url: 'hiker://empty', col_type: 'text_center_1' });
      setResult(d); return;
    }
    var html = this.get(url);
    var body = '';
    var m = html.match(/<article[^>]*>([\s\S]*?)<\/article>/i);
    if(m) body = m[1];
    if(!body){
      m = html.match(/class="[^"]*(?:content|novel|article|text)[^"]*"[^>]*>([\s\S]{200,})/i);
      if(m) body = m[1].substring(0, 100000);
    }
    body = body
      .replace(/<script[\s\S]*?<\/script>/gi, '')
      .replace(/<style[\s\S]*?<\/style>/gi, '')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/p>/gi, '\n')
      .replace(/<[^>]+>/g, '')
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&')
      .replace(/\n{3,}/g, '\n\n');
