          var t = tags[i];
          var sel = (tagUrl === t.url);
          var col = this.colorAt(i);
          d.push({
            title: t.name,
            url: $('#noLoading#').lazyRule(function(u){
              putVar('crdj_tag', u);
              refreshPage(true);
              return 'hiker://empty';
            }, t.url),
            col_type: 'scroll_button',
            extra: sel
              ? { backgroundColor: '#FF2D55', textColor: '#FFFFFF' }
              : { backgroundColor: col.bg, textColor: col.fg }
          });
        }
        d.push({ col_type: 'blank_block' });
      }
      if(!tagUrl && tags.length){
        tagUrl = tags[0].url;
        putVar('crdj_tag', tagUrl);
      }
      if(tagUrl){
        var listUrl = tagUrl;
        if(page > 1) listUrl = tagUrl.replace(/\/$/, '') + '/page/' + page + '/';
        var cards = this.parseCards(this.get(listUrl));
        if(!cards.length){
          d.push({ title: page > 1 ? '已经到底了' : '暂无内容', url: 'hiker://empty', col_type: 'text_center_1' });
        }else{
          this.pushCards(d, cards, '');
        }
      }
      setResult(d);
      return;
    }

    // ===== 其它分类 =====
    var path = '/';
    var kind = tab;
    for(var i = 0; i < this.cats.length; i++){
      if(this.cats[i].k === tab){ path = this.cats[i].path; break; }
    }

    var listPageUrl;
    if(tab === 'home'){
      listPageUrl = this.host + '/';
    }else if(tab === 'paihang'){
      listPageUrl = this.host + '/paihang/';
    }else{
      listPageUrl = this.listUrl(path, page);
    }

    var html = this.get(listPageUrl);
    var cards = this.parseCards(html);
    if(page === 1){
      d.push({
        title: '精选内容',
        url: 'hiker://empty',
        col_type: 'text_1',
        extra: { backgroundColor: '#FFFFFF', textColor: '#111827', textSize: 16, lineVisible: false }
      });
    }

    // 首页：网站本身「官方推荐/热播/短剧」有重复，已按 URL 去重
    if(!cards.length){
      d.push({ title: page > 1 ? '已经到底了' : '暂无内容', url: 'hiker://empty', col_type: 'text_center_1' });
    }else{
      this.pushCards(d, cards, kind);
    }
    setResult(d);
  }
};

