  name: 'XiuRen秀人网',
  site: 'https://xiuren.biz',
  api: 'https://xiuren.biz/wp-json/wp/v2',
  ua: 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36',

  headers: function () {
    return { 'User-Agent': this.ua, 'Referer': this.site + '/' };
  },

  get: function (url) {
    try { return fetch(url, { headers: this.headers(), timeout: 15000 }) || ''; } catch (e) { return ''; }
  },
  getJson: function (url) {
    var raw = this.get(url);
    if (!raw) return null;
    try { return JSON.parse(raw); } catch (e) { return null; }
  },

  pageNo: function () {
    var p = parseInt(typeof MY_PAGE !== 'undefined' ? MY_PAGE : 0, 10);
    if (p >= 1) return p;
    var u = String(MY_URL || '');
    var m = u.match(/[?&]page=(\d+)/) || u.match(/\/page\/(\d+)/);
    return m ? (parseInt(m[1], 10) || 1) : 1;
  },

  decode: function (s) {
    s = String(s || '');
    s = s.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
         .replace(/&#0?39;|&apos;/g, "'").replace(/&nbsp;/g, ' ');
    for (var k = 0; k < 3; k++) {
      var prev = s;
      s = s.replace(/&#(\d+);/g, function (m, n) { try { return String.fromCharCode(parseInt(n, 10)); } catch (e) { return m; } });
      s = s.replace(/&#x([0-9a-fA-F]+);/g, function (m, n) { try { return String.fromCharCode(parseInt(n, 16)); } catch (e) { return m; } });
      s = s.replace(/&amp;/g, '&');
      if (s === prev) break;
    }
    return s;
  },
  clean: function (s) {
    if (!s) return '';
    return this.decode(String(s).replace(/<[^>]+>/g, '')).replace(/\s+/g, ' ').trim();
  },

  imgOk: function (u) {
    if (!u || u.indexOf('http') !== 0) return false;
    if (u.indexOf('/wp-content/uploads/') < 0 && u.indexOf('/uploads/') < 0) return false;
    if (!/\.(jpe?g|png|webp|gif|bmp|avif)(\?|#|$)/i.test(u)) return false;
    if (/(?:^|\/)(?:ads?|banner|logo|avatar|gravatar)[-_.\/]|jeg-empty|placeholder|spinner|\/emoji\/|\/plugins\/|\/themes\/|favicon|blank\./i.test(u)) return false;
    if (/\.svg(\?|#|$)/i.test(u)) return false;
    return true;
  },
  stem: function (u) {
    return String(u || '').replace(/-\d{2,4}x\d{2,4}(?=\.[A-Za-z0-9]+(\?|#|$))/i, '');
  },
  pickImg: function (tag) {
    var s = String(tag || ''), m;
    m = s.match(/\bsrc\s*=\s*["']([^"']+)["']/i);
    if (m && m[1] && m[1].indexOf('data:image') !== 0) return m[1];
    var keys = ['data-src', 'data-lazy-src', 'data-original', 'data-echo', 'data-url'];
    for (var i = 0; i < keys.length; i++) {
      var re = new RegExp(keys[i] + '\\s*=\\s*["\']([^"\']+)["\']', 'i');
      m = s.match(re);
      if (m && m[1] && m[1].indexOf('data:image') !== 0) return m[1];
    }
    m = s.match(/\bsrcset\s*=\s*["']([^"'\s,]+)/i);
    if (m && m[1]) return m[1];
    return '';
  },
  pic: function (p) {
    try {
      var em = p && p._embedded && p._embedded['wp:featuredmedia'];
      if (em && em.length && em[0]) {
        var f = em[0];
        if (f.source_url) return f.source_url;
        var sz = f.media_details && f.media_details.sizes;
        if (sz) return (sz.full && sz.full.source_url) || (sz.large && sz.large.source_url) || (sz.medium_large && sz.medium_large.source_url) || (sz.medium && sz.medium.source_url) || '';
      }
    } catch (e) {}
    return '';
  },

  imgs: function (html) {
    if (!html) return [];
    var h = this.decode(html);
    var self = this, fullOf = {}, m;
    var reA = /<a[^>]+href=["']([^"']+\.(?:jpe?g|png|webp|gif|avif))["']/gi;
    while ((m = reA.exec(h)) !== null) {
      var u0 = self.decode(m[1]).replace(/\\/g, '');
      if (self.imgOk(u0)) fullOf[self.stem(u0)] = u0;
    }
    var out = [], seen = {}, reI = /<img[^>]*>/gi;
    while ((m = reI.exec(h)) !== null) {
      var raw = self.pickImg(m[0]);
      if (!raw) continue;
      var u2 = self.decode(raw).replace(/\\/g, '');
      if (u2.indexOf('//') === 0) u2 = 'https:' + u2;
      if (u2.indexOf('http') !== 0) { if (u2.indexOf('/') === 0) u2 = self.site + u2; else continue; }
      if (!self.imgOk(u2)) continue;
      var full = fullOf[self.stem(u2)];
      if (full && !/-\d{2,4}x\d{2,4}(?=\.[A-Za-z0-9]+$)/.test(full)) u2 = full;
      if (seen[u2]) continue;
      seen[u2] = 1; out.push(u2);
    }
    return out;
  },

  fin: function (u) {
    if (!u) return '';
    return /\.[A-Za-z0-9]+(\?|#|$)/i.test(u) ? u + '#.jpg' : u + '#.jpg';
  },

  card: function (p) {
    var t = this.clean(p.title ? p.title.rendered : '');
    return {
      title: t || ('作品 ' + p.id),
      img: this.pic(p),
      url: this.api + '/posts/' + p.id + '#immersiveTheme#@rule=js:$.require("xiu").detail()',
      col_type: 'movie_3'
    };
  },

  LIST: function () { return '#immersiveTheme#@rule=js:$.require("xiu").list()'; },

  // ---------- 最新发布（大图卡片用） ----------
  latest: function (n) {
    return this.getJson(this.api + '/posts?page=1&orderby=date&order=desc&per_page=' + (n || 6) + '&_embed=wp:featuredmedia') || [];
  },

  // ---------- 首页（美化版） ----------
  home: function () {
    var d = [], self = this, L = self.LIST();
    var latestUrl = self.api + '/posts?page=fypage&orderby=date&order=desc&per_page=20&_embed=wp:featuredmedia' + L;

    // 1) 顶部快捷入口（text_4 纯文字，不依赖图片，杜绝 SVG 加载失败的空白）
    d.push({ title: '📣 最新', img: '', url: latestUrl, col_type: 'text_4' });
    d.push({ title: '🔥 月榜', img: '', url: self.site + '/popular-this-month/page/fypage/' + L, col_type: 'text_4' });
    d.push({ title: '🔺 周榜', img: '', url: self.site + '/popular-this-week/page/fypage/' + L, col_type: 'text_4' });
    d.push({ title: '🎲 随机', img: '', url: self.api + '/posts?page=1&per_page=20&orderby=rand&_embed=wp:featuredmedia' + L, col_type: 'text_4' });

    // 2) 分类（拉取一次，后面复用）
    var cats = self.getJson(self.api + '/categories?per_page=100&orderby=count&order=desc&_fields=id,slug,name,count');
    var valid = [];
    if (cats && cats.length) {
      for (var i = 0; i < cats.length && valid.length < 18; i++) {
        var c = cats[i];
        if (!c || !c.id || !c.slug) continue;
        if (c.slug === 'uncategorized') continue;
        if (!c.count || c.count <= 0) continue;
        valid.push(c);
      }
    }

    // 3) 横向滚动分类条（scroll_button 自动聚合）
    if (valid.length) {
      for (var k = 0; k < valid.length; k++) {
        // scroll_button 的跳转用 url 字段（skill 权威范式：url: $('...').lazyRule(...)）
        d.push({
          title: self.clean(valid[k].name || valid[k].slug),
          img: '',
          url: self.api + '/posts?categories=' + valid[k].id + '&page=fypage&orderby=date&order=desc&per_page=20&_embed=wp:featuredmedia' + L,
          col_type: 'scroll_button'
        });
      }
    }

    // 4) 最新发布（取真实封面做卡片）
    var lat = self.latest(6);
    if (lat.length) {
      d.push({ title: '<font color="#FF5D50"><b>▎最新发布</b></font>', img: '', url: latestUrl, col_type: 'rich_text', extra: { textSize: 16 } });
      for (var j = 0; j < lat.length && j < 2; j++) {
        if (!lat[j] || !lat[j].id) continue;
        var pu = self.pic(lat[j]);
        d.push({
          title: self.clean(lat[j].title ? lat[j].title.rendered : ''),
          img: pu, desc: '',
          url: self.api + '/posts/' + lat[j].id + '#immersiveTheme#@rule=js:$.require("xiu").detail()',
          col_type: 'card_pic_2',
          extra: { desc: 12 }
        });
      }
    }

    // 5) 各分类热门预览（三列网格）
    for (var n = 0; n < valid.length && n < 3; n++) {
      var cc = valid[n];
      var arr = self.getJson(self.api + '/posts?categories=' + cc.id + '&page=1&orderby=date&order=desc&per_page=6&_embed=wp:featuredmedia');
      if (!arr || !arr.length) continue;
      d.push({
        title: '📂 ' + self.clean(cc.name || cc.slug) + '  ·  ' + cc.count + ' 部',
        img: '',
        url: self.api + '/posts?categories=' + cc.id + '&page=fypage&orderby=date&order=desc&per_page=20&_embed=wp:featuredmedia' + L,
        col_type: 'rich_text', extra: { textSize: 15 }
      });
      for (var q = 0; q < arr.length && q < 6; q++) {
        if (!arr[q] || !arr[q].id) continue;
        d.push({
          title: self.clean(arr[q].title ? arr[q].title.rendered : ''),
          img: self.pic(arr[q]),
          url: self.api + '/posts/' + arr[q].id + '#immersiveTheme#@rule=js:$.require("xiu").detail()',
          col_type: 'movie_3'
        });
      }
    }

    if (d.length < 5) d.push({ title: '加载失败,请下拉刷新重试', img: '', url: 'hiker://empty', col_type: 'text_1' });
    setResult(d);
  },

  // ---------- 二级列表 ----------
  list: function () { setResult(this.listData()); },
  listData: function () {
    var u = String(MY_URL || '').split('#')[0].split('@rule')[0];
    if (u.indexOf('/popular-this-') >= 0) { return this.hotData(u); }
    u = u.replace(/([?&])page=(?:fypage|\d+)/g, '$1page=' + this.pageNo());
    return this.cards(this.getJson(u));
  },
  cards: function (arr) {
    var d = [], self = this;
    if (arr && arr.length) {
      var n = Math.min(arr.length, 40);
      for (var i = 0; i < n; i++) if (arr[i] && arr[i].id) d.push(self.card(arr[i]));
    }
    if (!d.length) d.push({ title: '暂无内容,下拉刷新重试', img: '', url: 'hiker://empty', col_type: 'text_1' });
    return d;
  },

  // ---------- 热门榜 ----------
  hotData: function (url) {
    var d = [], self = this;
    var base = String(url || '').replace(/\/page\/(?:fypage|\d+)\/?$/i, '').replace(/\/+$/, '');
    var pg = self.pageNo();
    var target = pg > 1 ? base + '/page/' + pg + '/' : base + '/';
    var html = self.get(target);
    if (!html) html = self.get(base + '/');

    var arts = html.match(/<article[^>]*>[\s\S]*?<\/article>/g) || [];
    var seen = {};
    for (var i = 0; i < arts.length && d.length < 40; i++) {
      var a = arts[i];
      var hm = a.match(/<a[^>]+href="(https?:\/\/[^"]+)"/);
      if (!hm) continue;
      var link = hm[1];
      if (link.indexOf('xiuren.biz') < 0) continue;
      if (/\/(category|tag|page|author)\//.test(link)) continue;
      if (seen[link]) continue;
      seen[link] = 1;

      var tm = a.match(/class="[^"]*jeg_post_title[^"]*"[^>]*>[\s\S]*?<a[^>]*>([\s\S]*?)<\/a>/i)
            || a.match(/<h3[^>]*>[\s\S]*?<a[^>]*>([\s\S]*?)<\/a>/i);
      var title = self.clean(tm ? tm[1] : '');
      if (!title) continue;

      var pm = self.pickImg(a);
      var picUrl = pm && self.imgOk(pm) ? pm : '';

      var idm = a.match(/(?:id="post-|postid-|data-post-id[=:]["']?)(\d+)/);
      var tail = link.replace(/\/+$/, '').split('/').pop();
      var du = idm ? self.api + '/posts/' + idm[1]
                   : self.api + '/posts?slug=' + encodeURIComponent(decodeURIComponent(tail)) + '&per_page=1';

      d.push({
        title: title, img: picUrl,
        url: du + '#immersiveTheme#@rule=js:$.require("xiu").detail()',
        col_type: 'movie_3'
      });
    }
    if (!d.length) d.push({ title: '该榜单暂无内容,下拉刷新重试', img: '', url: 'hiker://empty', col_type: 'text_1' });
    return d;
  },

  // ---------- 搜索 ----------
  search: function () {
    var kw = getMyVar('keyword') || (typeof MY_KEYWORD !== 'undefined' ? MY_KEYWORD : '') || '';
    kw = String(kw).trim();
    var d = [], self = this;
    if (!kw) { setResult([{ title: '请输入搜索关键词', img: '', url: 'hiker://empty', col_type: 'text_1' }]); return; }

    var arr = self.getJson(self.api + '/posts?search=' + encodeURIComponent(kw) + '&page=' + self.pageNo() + '&orderby=relevance&per_page=20&_embed=wp:featuredmedia');
    if (arr && arr.length) {
      for (var i = 0; i < arr.length; i++) if (arr[i] && arr[i].id) d.push(self.card(arr[i]));
    }
    if (!d.length) {
      var html = self.get(self.site + '/?s=' + encodeURIComponent(kw));
      var arts = html.match(/<article[^>]*>[\s\S]*?<\/article>/g) || [];
      var seen = {};
      for (var k = 0; k < arts.length && k < 30; k++) {
        var a = arts[k];
        var hm = a.match(/<a[^>]+href="(https?:\/\/[^"]+)"/); if (!hm) continue;
        var link = hm[1];
        if (link.indexOf('xiuren.biz') < 0 || /\/(category|tag|page|author)\//.test(link)) continue;
        if (seen[link]) continue; seen[link] = 1;
        var tm = a.match(/class="[^"]*jeg_post_title[^"]*"[^>]*>[\s\S]*?<a[^>]*>([\s\S]*?)<\/a>/i);
        var title = self.clean(tm ? tm[1] : ''); if (!title) continue;
        var pm = self.pickImg(a);
        var idm = a.match(/(?:id="post-|postid-|data-post-id[=:]["']?)(\d+)/);
        var tail = link.replace(/\/+$/, '').split('/').pop();
        var du = idm ? self.api + '/posts/' + idm[1]
                     : self.api + '/posts?slug=' + encodeURIComponent(decodeURIComponent(tail)) + '&per_page=1';
        d.push({ title: title, img: pm && self.imgOk(pm) ? pm : '', url: du + '#immersiveTheme#@rule=js:$.require("xiu").detail()', col_type: 'movie_3' });
      }
    }
    if (!d.length) d.push({ title: '没搜到「' + kw + '」相关内容', img: '', url: 'hiker://empty', col_type: 'text_1' });
    setResult(d);
  },

  // ---------- 详情 ----------
  detail: function () {
    var u = String(MY_URL || ''), self = this;
    var head = u.split('#')[0].split('@rule')[0];

    if (head.indexOf('/popular-this-') >= 0) { setResult(this.hotData(head)); return; }
    if (head.indexOf('/posts?') >= 0 && head.indexOf('slug=') < 0) { setResult(this.listData()); return; }

    var post = null;
    var idm = u.match(/\/posts\/(\d+)/);
    if (idm) post = self.getJson(self.api + '/posts/' + idm[1]);

    if (!post) {
      var slug = '';
      var sm = head.match(/[?&]slug=([^&]+)/);
      if (sm) { try { slug = decodeURIComponent(sm[1]); } catch (e) { slug = sm[1]; } }
      if (!slug) {
        var raw = head.split('?')[0].replace(/\/+$/, '').split('/').pop();
        if (raw && raw !== 'posts') { try { slug = decodeURIComponent(raw); } catch (e) { slug = raw; } }
      }
      if (slug) {
        var q = self.getJson(self.api + '/posts?slug=' + encodeURIComponent(slug) + '&per_page=1');
        if (q && q.length) post = q[0];
      }
    }
    if (!post) {
      var page = self.get(head);
      var seg = page;
      var mm = page.match(/<div class="[^"]*(?:entry-content|jeg_inner_content|content-inner)[^"]*"[^>]*>([\s\S]*?)<div class="[^"]*(?:jeg_share|jeg_post_tags|jeg_prevnext|jeg_post_nav)[^"]*"/i);
      if (mm) seg = mm[1];
      var tt = page.match(/<h1[^>]*class="[^"]*jeg_post_title[^"]*"[^>]*>([\s\S]*?)<\/h1>/i);
      if (!tt) { var om = page.match(/<meta[^>]+(?:property|name)=["']og:title["'][^>]*>/i); if (om) { var cm = om[0].match(/content=["']([^"']+)["']/i); if (cm) tt = ['', cm[1]]; } }
      if (!tt) { var t2 = page.match(/<title>([^<]*)<\/title>/i); if (t2) tt = ['', t2[1]]; }
      if (seg && /^\s*[[{]/.test(seg)) seg = '';
      if (seg || tt) post = { content: { rendered: seg || '' }, title: { rendered: tt ? tt[1] : '' }, link: head };
    }

    if (!post) { setResult([{ title: '详情获取失败,稍后重试', img: '', url: 'hiker://empty', col_type: 'text_1' }]); return; }

    var title = post.title ? self.clean(post.title.rendered) : '';
    var body = (post.content && post.content.rendered) || '';
    var imgs = self.imgs(body);

    var d = [];
    if (imgs.length) {
      d.push({ title: title, desc: '共 ' + imgs.length + ' 张', img: self.fin(imgs[0]), url: 'javascript:;', col_type: 'movie_1_vertical_pic_blur' });
      var urls = [];
      for (var j = 0; j < imgs.length; j++) urls.push(self.fin(imgs[j]));
      d.push({
        title: '查看全部 ' + imgs.length + ' 张',
        img: self.fin(imgs[0]),
        url: 'pics://' + urls.join('&&'),
        col_type: 'pic_1'
      });
    } else {
      d.push({
        title: title || '未解析到图片',
        desc: '正文 ' + String(body).length + ' 字符 | 片段: ' + String(body).replace(/\s+/g, ' ').slice(0, 200),
        img: '', url: 'hiker://empty', col_type: 'text_1'
      });
    }
    setResult(d);
  }
};
$.exports = engine;

