var d=[];
function jdbText(v){
    if(v===undefined||v===null)return '';
    if(typeof v==='string'||typeof v==='number'||typeof v==='boolean')return String(v);
    if(v instanceof Array){var a=[];for(var i=0;i<v.length;i++){var t=jdbText(v[i]);if(t)a.push(t);}return a.join('、');}
    if(typeof v==='object'){
        var keys=['name_zht','name','title','label','text','number','username'];
        for(var k=0;k<keys.length;k++){if(v[keys[k]]!==undefined&&v[keys[k]]!==null){var s=jdbText(v[keys[k]]);if(s)return s;}}
    }
    return '';
}
