let page=String((MY_PARAMS&&MY_PARAMS.subtitle_page)||'');
let title=String((MY_PARAMS&&MY_PARAMS.subtitle_name)||'字幕');
function abs(base,u){
u=String(u||'').trim();
if(/^https?:\/\//i.test(u))return u;
if(/^\/\//.test(u))return 'https:'+u;
return base.replace(/\/$/,'')+'/'+u.replace(/^\//,'');
}
function clean(s){return String(s||'').replace(/<[^>]+>/g,' ').replace(/&amp;/gi,'&').replace(/&nbsp;/gi,' ').replace(/\s+/g,' ').trim();}
if(!page){
d.push({title:'字幕详情地址为空',url:'hiker://empty',col_type:'text_center_1'});
setResult(d);
}else{
let h='',err='';
try{
h=fetchCodeByWebView(page,{
headers:{'User-Agent':PC_UA,'Referer':'https://www.subtitlecat.com/'},
blockRules:['.jpg','.jpeg','.png','.gif','google','doubleclick','analytics'],
timeout:18000,
checkJs:$.toString(()=>{
if(document.querySelector('a[href*="download"]'))return document.body;
if(document.readyState==='complete'&&document.body&&document.body.innerText.length>200)return document.body;
return null;
})
})||'';
}catch(e){err=String(e.message||e);}
d.push({title:title,desc:'SubtitleCat 内部解析',url:'hiker://empty',col_type:'text_1',extra:{lineVisible:false}});

let rows=[],m,re=/<tr\b[^>]*>([\s\S]*?)<\/tr>/gi;
while((m=re.exec(String(h||'')))!==null){
let row=m[1],text=clean(row);
if(!/Download/i.test(text))continue;
let lm=text.match(/Chinese \(Simplified\)|Chinese \(Traditional\)|English|Japanese|Korean|Indonesian|Thai|German|French|Spanish/i);
let lang=lm?lm[0]:text.slice(0,80);
let am,ar=/<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi,download='';
while((am=ar.exec(row))!==null){
if(/Download/i.test(clean(am[2]))){download=abs('https://www.subtitlecat.com',am[1]);break;}
}
if(download)rows.push({lang:lang,url:download});
}
let priority={'Chinese (Simplified)':0,'Chinese (Traditional)':1,'English':2,'Japanese':3,'Korean':4};
rows.sort((a,b)=>(priority[a.lang]??99)-(priority[b.lang]??99));

rows.forEach(x=>d.push({
title:x.lang+' · 下载',
desc:x.url.replace(/^https?:\/\//,'').split('/')[0],
url:x.url,
col_type:'text_1',
extra:{lineVisible:false,longClick:[
{title:'复制下载地址',js:$.toString((u)=>'copy://'+u,x.url)}
]}
}));
if(!rows.length)d.push({
title:'详情页已加载，但没有识别到下载链接',
desc:err||'可能页面结构变化或需要浏览器验证',
url:'web://'+page,
col_type:'text_center_1'
});
setResult(d);
}

