 let body='';try{body=String(fetch(master,{headers:h,timeout:7000})||'');}catch(e){}let lines=body.replace(/\r/g,'').split('\n'),best=null;for(let i=0;i<lines.length;i++){if(lines[i].indexOf('#EXT-X-STREAM-INF:')!==0)continue;let info=lines[i],j=i+1;while(j<lines.length&&(!lines[j].trim()||lines[j].trim()[0]==='#'))j++;if(j>=lines.length)continue;let u=abs(master,lines[j].trim()),rm=info.match(/RESOLUTION=\d+x(\d+)/i),bm=info.match(/BANDWIDTH=(\d+)/i),hh=rm?parseInt(rm[1],10):0,bb=bm?parseInt(bm[1],10):0;if(!best||hh>best.h||(hh===best.h&&bb>best.b))best={url:u,h:hh,b:bb};}let play=(best&&best.url)||master;return play+';{Referer@'+url+'&&Origin@'+org+'}';}
