function jdbQs(o){var a=[];for(var k in o){if(!o.hasOwnProperty(k))continue;var v=o[k];if(v===undefined||v===null||String(v)==='')continue;a.push(encodeURIComponent(k)+'='+encodeURIComponent(String(v)));}return a.join('&');}
