    var url='https://jdforrepam.com'+path;var q=jdbQs(params||{});if(q)url+=(url.indexOf('?')>=0?'&':'?')+q;
    var raw=fetch(url,{headers:{'jdsignature':jdbSignature(),'user-agent':'Dart/3.5 (dart:io)','accept':'application/json','accept-language':'zh-TW','host':'jdforrepam.com','connection':'keep-alive'},timeout:16000,withStatusCode:true});
