    d.push({title:'搜索',desc:'番号 / 演员 / 影片 / 系列 / 片商 / 导演',url:$.toString(function(){var v=String(input||'').trim();if(!v)return 'toast://请输入搜索内容';try{var h=JSON.parse(getItem('jdb3_search_history','[]'));if(!(h instanceof Array))h=[];var n=[v];for(var i=0;i<h.length&&n.length<12;i++){if(String(h[i])!==v)n.push(String(h[i]));}setItem('jdb3_search_history',JSON.stringify(n));}catch(e){}return 'hiker://page/javdb3Search?page=fypage&rule=&simple=true&word='+encodeURIComponent(v);}),col_type:'input',extra:{defaultValue:kw||'',backgroundColor:'#F6F7F8'}});
}
function jdbTab(title,value,current){var on=value===current;d.push({title:(on?'✓ ':'')+title,url:$('#noLoading#').lazyRule(function(v){putMyVar('jdb3_search_type',v);refreshPage(false);return 'hiker://empty';},value),col_type:'scroll_button',extra:{backgroundColor:on?'#39B875':'#F2F3F5',lineVisible:false}});}
function jdbSmallChip(title,key,value,current){var on=value===current;d.push({title:(on?'✓ ':'')+title,url:$('#noLoading#').lazyRule(function(k,v){putMyVar(k,v);refreshPage(false);return 'hiker://empty';},key,value),col_type:'scroll_button',extra:{backgroundColor:on?'#E5F7EE':'#F5F5F5',lineVisible:false}});}
function jdbMovieCard(x){x=x||{};var id=String(x.id||'');var num=jdbClean(x.number||'');var title=jdbClean(x.title||x.origin_title||num||'未命名');var show=num?(num+' · '+title):title;var meta=[];if(x.release_date)meta.push(jdbClean(x.release_date));if(x.duration)meta.push(String(x.duration)+' 分钟');if(x.magnets_count!==undefined&&x.magnets_count!==null)meta.push('磁链 '+String(x.magnets_count));if(x.can_play)meta.push('可播放');return{title:show,desc:meta.join(' · '),pic_url:jdbImg(x.cover_url||x.thumb_url||''),img:jdbImg(x.cover_url||x.thumb_url||''),url:'hiker://page/javdb3Detail?rule=&simple=true',col_type:'movie_2',extra:{lineVisible:false,jdb3_id:id,pageTitle:num||title}};}
function jdbEntityCard(x,type){x=x||{};var id=String(x.id||'');var title=jdbClean(x.name_zht||x.name||x.title||x.number||'未命名');var meta=[];if(type==='actor'){if(x.name&&x.name_zht&&String(x.name)!==String(x.name_zht))meta.push(jdbClean(x.name));var other=jdbText(x.other_name);if(other)meta.push(jdbClean(other));}if(x.videos_count!==undefined&&x.videos_count!==null)meta.push('作品 '+String(x.videos_count));var pic=type==='actor'?jdbImg(x.avatar_url||x.cover_url||''):'';return{title:title,desc:meta.join(' · '),pic_url:pic,img:pic,url:'hiker://page/javdb3Entity?page=fypage&rule=&simple=true',col_type:pic?'movie_1_left_pic':'text_2',extra:{lineVisible:false,jdb3_entity_type:type,jdb3_entity_id:id,pageTitle:title}};}
function jdbVariants(kw){var a=[kw],n=String(kw||'').replace(/\s+/g,'');if(n&&a.indexOf(n)<0)a.push(n);try{var s=String(java.t2s(kw)||'');if(s&&a.indexOf(s)<0)a.push(s);}catch(e){}try{var t=String(java.s2t(kw)||'');if(t&&a.indexOf(t)<0)a.push(t);}catch(e2){}return a;}
function jdbTypedSearch(kw,type){var vars=jdbVariants(kw),key=type==='actor'?'actors':type==='series'?'series':type==='maker'?'makers':type==='director'?'directors':'codes';var out=[],seen={};for(var i=0;i<vars.length&&out.length<30;i++){try{var r=jdbApiPath('/api/v2/search',{q:vars[i],page:1,type:type});var a=r[key]||[];for(var j=0;j<a.length;j++){var id=String(a[j].id||type+'_'+j+'_'+jdbText(a[j].name||a[j].number));if(!seen[id]){seen[id]=1;out.push(a[j]);}}}catch(e){}}return out;}
function jdbMatchEntity(e,kw,type){var needle=jdbNorm(kw);if(!needle)return false;var vals=[];if(type==='actor'){vals=[e.name,e.name_zht,e.other_name];}else{vals=[e.name,e.title,e.number];}for(var i=0;i<vals.length;i++){var s=jdbNorm(vals[i]);if(s&&(s.indexOf(needle)>=0||needle.indexOf(s)>=0))return true;}return false;}
function jdbDetailEntity(x,type){if(!x)return null;if(type==='actor')return x.actors||[];if(type==='series'){var s=x.series||null;if(!s&&x.series_id)s={id:x.series_id,name:x.series_name||''};return s?[s]:[];}if(type==='maker'){var m=x.maker||null;if(!m&&x.maker_id)m={id:x.maker_id,name:x.maker_name||''};return m?[m]:[];}if(type==='director'){var d0=x.director||null;if(!d0&&x.director_id)d0={id:x.director_id,name:x.director_name||''};return d0?[d0]:[];}return [];}
function jdbFallbackFromMovies(kw,type){
    if(type==='code')return [];
    var search;try{search=jdbApiPath('/api/v2/search',{q:kw,page:1,type:'movie',movie_type:'all',movie_sort_by:'relevance',movie_filter_by:'all'});}catch(e){try{search=jdbApiPath('/api/v2/search',{q:kw,page:1});}catch(e2){return [];}}
    var movies=search.movies||[],out=[],seen={},max=Math.min(movies.length,8);
    for(var i=0;i<max;i++){
        var id=String((movies[i]&&movies[i].id)||'');if(!id)continue;
        try{var rd=jdbApiPath('/api/v4/movies/'+encodeURIComponent(id),{});var x=rd.movie||rd;var arr=jdbDetailEntity(x,type);for(var j=0;j<arr.length;j++){var e=arr[j]||{};if(!jdbMatchEntity(e,kw,type))continue;var eid=String(e.id||'');if(!eid||seen[eid])continue;seen[eid]=1;out.push(e);}}catch(_e){}
        if(out.length>=12)break;
    }
    return out;
}
function jdbMergeUnique(a,b){var out=[],seen={};function add(x){var id=String((x&&x.id)||'');if(!id)id=jdbNorm(jdbText(x&&x.name||x&&x.number||''));if(!id||seen[id])return;seen[id]=1;out.push(x);}for(var i=0;i<a.length;i++)add(a[i]);for(var j=0;j<b.length;j++)add(b[j]);return out;}
var kw='';try{kw=String(getParam('word')||getParam('q')||'').trim();try{kw=decodeURIComponent(kw.replace(/\+/g,'%20'));}catch(_de){}kw=kw.trim();}catch(e){kw='';}
