        d.push({col_type:'blank_block'});
        try{var h=JSON.parse(getItem('jdb3_search_history','[]'));if(h instanceof Array&&h.length>1){var hasHistory=false;for(var hi=0;hi<h.length&&hi<7;hi++){var hv=String(h[hi]||'').trim();if(!hv||hv===kw)continue;if(!hasHistory){d.push({title:'最近搜索 · 长按可删',url:'hiker://empty',col_type:'text_1',extra:{lineVisible:false}});d.push({title:'清空全部',url:$('#noLoading#').lazyRule(function(){setItem('jdb3_search_history','[]');putMyVar('jdb3_history_skip_once','1');refreshPage(false);return 'toast://搜索记录已清空';}),col_type:'scroll_button',extra:{backgroundColor:'#F5F5F5',lineVisible:false}});hasHistory=true;}d.push({title:hv,url:'hiker://page/javdb3Search?page=fypage&rule=&simple=true&word='+encodeURIComponent(hv),col_type:'scroll_button',extra:{backgroundColor:'#F5F5F5',lineVisible:false,longClick:[{title:'删除 '+hv,js:$.toString(function(v){try{var h=JSON.parse(getItem('jdb3_search_history','[]'));if(!(h instanceof Array))h=[];var n=[];for(var i=0;i<h.length;i++){if(String(h[i])!==String(v))n.push(String(h[i]));}setItem('jdb3_search_history',JSON.stringify(n));refreshPage(false);return 'toast://已删除';}catch(e){return 'toast://删除失败';}},hv)}]}});}}}catch(_h){}
        d.push({col_type:'blank_block'});
