                    d.push({col_type:'blank_block'});jdbSmallChip('相关','jdb3_search_movie_sort','relevance',sort);jdbSmallChip('发行','jdb3_search_movie_sort','release',sort);jdbSmallChip('更新','jdb3_search_movie_sort','update',sort);jdbSmallChip('评分','jdb3_search_movie_sort','score',sort);d.push({col_type:'blank_block'});
                }
                filter=getMyVar('jdb3_search_movie_filter','all');sort=getMyVar('jdb3_search_movie_sort','relevance');
                var data;try{data=jdbApiPath('/api/v2/search',{q:kw,page:page,type:'movie',movie_type:'all',movie_sort_by:sort,movie_filter_by:filter});}catch(eMovie){data=jdbApiPath('/api/v2/search',{q:kw,page:page});}
                var movies=data.movies||[];if(page===1)jdbSection('影片',String(movies.length)+' 条');for(var mi=0;mi<movies.length;mi++)d.push(jdbMovieCard(movies[mi]));if(!movies.length&&page===1)d.push({title:'没有找到相关影片',desc:'可以切换上方其它分类继续搜索',url:'hiker://empty',col_type:'text_center_1'});
            }else{
