const Tool = $.require("hiker://page/Tool.js");
const Config = $.require("hiker://page/Config.json");

viewConfig.info.bookName=Tool.textShield(viewConfig.info.bookName);
viewConfig.info.ruleName=Tool.textShield(viewConfig.info.ruleName);

const def_DoVi_Style = Config.def_DoVi_Style;
const MY_ID = info.ruleName + "//" + info.bookName;

let isStart = getMyVar(MY_ID + ":isStart");
let viewMode = getMyVar(MY_ID + ":viewMode", defaultView);
