let tagFilter = getMyVar(MY_ID + ":tagFilter", Config.def_DoVi_Type);

addListener("onClose", $.toString((MY_ID) => {
    clearMyVar(MY_ID + ":loadingTeam");
    clearMyVar(MY_ID + ":viewMode");
    clearMyVar(MY_ID + ":completed");
    clearMyVar(MY_ID + ":batchTeam");
    clearMyVar(MY_ID + ":tagFilter");
    clearMyVar(MY_ID + ":pageNum");
}, MY_ID));

let layout = [];

if (isStart === "1") {
    putMyVar(MY_ID + ":viewMode", defaultView);
    viewMode = "1";
}

let backupChapterList = chapterList;
if (typeof chapterList === "string") {
    chapterList = JSON.parse(request("file://" + chapterList) || "[]");
}
let chapterAll = chapterList;
chapterList = chapterList.map((item, CID) => {
    item.CID = CID;
    item.title=Tool.textShield(item.title);
    return item;
});
let pageNum = Number(getMyVar(MY_ID + ":pageNum", "1"));
let chapterChunk = [chapterList].concat(Tool.chunk(chapterList, Config.viewPageSize));
chapterList = chapterChunk[pageNum] || [];

function setType() {
    let set = (tag, put) => {
        putMyVar(put, tag);
        refreshPage(false);
        return "hiker://empty"
    };
    layout.push({
        title: 0 == pageNum ? "““””" + ("全部(" + chapterAll.length + ")").fontcolor("#23AD6F") : "全部(" + chapterAll.length + ")",
        url: $("#noLoading#").lazyRule(set, 0, MY_ID + ":pageNum"),
        col_type: "scroll_button"
    });
    for (let i = 1; i < chapterChunk.length; i++) {
        let tagText = (i - 1) * Config.viewPageSize + "-" + ((i - 1) * Config.viewPageSize + chapterChunk[i].length);
        layout.push({
            title: i == pageNum ? "““””" + tagText.fontcolor("#23AD6F") : tagText,
            url: $("#noLoading#").lazyRule(set, i, MY_ID + ":pageNum"),
            col_type: "scroll_button"
        });
    }
    layout.push({
        col_type: "blank_block"
    });
    layout.push({
        title: tagFilter === "0" ? "““””" + "全部".fontcolor("#23AD6F") : "全部",
        url: $("#noLoading#").lazyRule(set, "0", MY_ID + ":tagFilter"),
        col_type: "scroll_button"
    });
    layout.push({
        title: tagFilter === "1" ? "““””" + "未下载".fontcolor("#23AD6F") : "未下载",
        url: $("#noLoading#").lazyRule(set, "1", MY_ID + ":tagFilter"),
        col_type: "scroll_button"
    });
    layout.push({
        title: tagFilter === "2" ? "““””" + "已下载".fontcolor("#23AD6F") : "已下载",
        url: $("#noLoading#").lazyRule(set, "2", MY_ID + ":tagFilter"),
        col_type: "scroll_button"
    });
}
let chapterTeam = [];
let record = [];
if (info.type === "comic") {
    let lazy = $("#noLoading#").lazyRule(() => {
        const File = $.require("hiker://page/File.js");
        let filelist = File.getFilePath(input);
        let piclist = filelist.map((item, i) => "file://" + input + "/" + (i + 1) + ".jpg");
        return "pics://" + piclist.join("&&");
    });

    function comFun(i, item) {
        let rootPath = Config.comicPath + "/" + info.ruleName + "/" + info.bookName + "/" + i + "$A$" + item.title;
        return {
            title: "““" + item.title + "””",
            url: rootPath + lazy,
            extra: {
                id: MY_ID + "#" + i,
            },
            col_type: def_DoVi_Style
        }
    }
    File.getFilePath(Config[info.type + "Path"] + "/" + info.ruleName + "/" + info.bookName, "dir").forEach((file) => {
        let att = Tool.split(file.name, "$", 2);
        if (att.length === 3 && att[1] === ("A")) {
            record.push(att[2]);
        }
    });
} else {
    function comFun(i, item) {
        return {
            title: "““" + item.title + "””",
            url: "hiker://page/NovelMainBody#autoPage##readTheme#",
            extra: {
                id: MY_ID + "#" + i,
                path: Config.novelPath + "/" + info.ruleName + "/" + info.bookName + "/" + i + "$A$" + item.title + ".txt",
                title: item.title
            },
            col_type: def_DoVi_Style
        }
    }
    File.getFilePath(Config[info.type + "Path"] + "/" + info.ruleName + "/" + info.bookName, "file", ".txt").forEach((file) => {
        let att = Tool.split(file.name, "$", 2);
        if (att.length === 3 && att[1] === ("A")) {
            record.push(att[2].slice(0, att[2].lastIndexOf(".")));
        }
    });
}

function clickDownload(item, info, MY_ID, i) {
    let loadingTeam = JSON.parse(getMyVar(MY_ID + ":loadingTeam", "[]") || "[]");
    let ElementIndex = loadingTeam.indexOf(i);
    if (ElementIndex > -1) return "toast://正在下载";

    loadingTeam.push(i);
