const File = $.require("hiker://page/File.js?rule=" + MY_RULE._title);
const Config = $.require("hiker://page/Config.json?rule=" + MY_RULE._title);
let comicRuleDirs = File.getFilePath(Config[getParam("type") + "Path"], "dir");
if (getParam("isAll") === "1") {
    comicRuleDirs = comicRuleDirs.filter(item => item.name === MY_RULE.title);
}

let searchResult = [];
let searchTerms= getParam("searchTerms");
let searchTest;

if (!getSearchMode()) {
    let termsArr = searchTerms.split("").map(t => t.replace(/\*|\.|\?|\+|\$|\^|\[|\]|\(|\)|\{|\}|\||\/|\\/g, k => "\\" + k));
    let reg = new RegExp(termsArr.join(".*"), "i");
    searchTest = text => reg.test(text);
} else {
    searchTest = text => searchContains(text, searchTerms, false);
}

let pageUrl = getParam("type") === "novel" ? "hiker://page/NovelBrowser.view" : "hiker://page/ComicBrowser.view";
for (let sonDir of comicRuleDirs) {
    let comicList = File.getFilePath(sonDir.path, "dir");
    for (let comic of comicList) {
        if (searchTest(comic.name)) {
            searchResult.push({
                title: comic.name,
                pic_url: comic.path + "/" + comic.name + ".jpg",
                url: pageUrl + "?rule=" + MY_RULE._title,
                desc: sonDir.name,
                extra: comic
            });
        }
    }

}
setResult(searchResult);

