function abs(u) {
  if (!u) return '';
  u = String(u).trim();
  if (u.indexOf('http') === 0) return u;
  if (u.indexOf('//') === 0) return 'https:' + u;
  if (u.indexOf('/') === 0) return HOST + u;
  return HOST + '/' + u;
}

function pageUrl(base, p) {
  base = String(base || '').replace(/\/?$/, '/');
  if (!p || p <= 1) return base;
  // /videos/new/2/  or  /videos/categories/xxx/2/
  return base + p + '/';
}

function catExtra(active) {
  return active
    ? { backgroundColor: '#E11D48', textColor: '#FFFFFF', lineVisible: false }
    : { backgroundColor: '#F3F4F6', textColor: '#374151', lineVisible: false };
}

function fetchHtml(url) {
  return fetch(url, {
    headers: {
      'User-Agent': UA,
      'Referer': HOST + '/',
      'Accept-Language': 'en-US,en;q=0.9'
    }
  });
}

// 播放：优先最高清晰度
var lazy = $("").lazyRule((host, ua) => {
  try {
    var html = fetch(input, {
      headers: { 'User-Agent': ua, 'Referer': host + '/' }
    });
    var srcs = pdfa(html, 'source') || [];
    if (!srcs.length) srcs = pdfa(html, '#main_video&&source') || [];
    var list = [];
    for (var i = 0; i < srcs.length; i++) {
      var s = srcs[i];
      var u = pdfh(s, 'source&&src') || pd(s, 'source&&src') || '';
      var t = pdfh(s, 'source&&title') || '';
      if (!u) continue;
      list.push({ u: u, t: t || ('线路' + (list.length + 1)) });
    }
    if (!list.length) return 'toast://未解析到播放地址';
    // 按分辨率排序，高的在前
    list.sort(function(a, b) {
      var ra = parseInt(String(a.t).replace(/\D/g, ''), 10) || 0;
      var rb = parseInt(String(b.t).replace(/\D/g, ''), 10) || 0;
      return rb - ra;
    });
    var urls = [];
    var names = [];
    for (var j = 0; j < list.length; j++) {
      urls.push(list[j].u + '#isVideo=true#');
      names.push(list[j].t);
    }
    return JSON.stringify({ urls: urls, names: names, headers: [{
      'User-Agent': ua,
      'Referer': host + '/',
      'Origin': host
    }] });
  } catch (e) {
    return 'toast://播放解析失败：' + e.message;
  }
}, HOST, UA);

function pushVideos(html) {
  var items = pdfa(html, 'body&&.item') || [];
