    if (!href || href.indexOf('/video/') < 0) continue;
    var title = pdfh(it, 'strong.title&&Text') || pdfh(it, 'img&&alt') || pdfh(it, 'a&&title') || '';
    var img = pd(it, 'img&&src') || pd(it, 'img&&data-jpg') || '';
