function jdb3ExternalFixApply(list, code) {
    try {
        if (!list || !list.length || !code) return 0;
        var map = {
            'https://img.vinua.cn/images/IQqwD.png': jdb3ExternalFix123av,     /* 𝟏𝟐𝟑𝐀𝐕 */
            'https://img.vinua.cn/images/IQBFU.png': jdb3ExternalFixBestjav,   /* 𝐁𝐞𝐬𝐭𝐉𝐚𝐯 */
            'https://img.vinua.cn/images/zHhaL.png': jdb3ExternalFixXszav,     /* 𝐗𝐒𝐙𝐀𝐕 */
            'https://img.vinua.cn/images/IQH1l.png': jdb3ExternalFixJavguru,   /* 𝐉𝐚𝐯𝐆𝐮𝐫𝐮 */
