        };
        var n = 0;
        for (var i = 0; i < list.length; i++) {
            var item = list[i];
            if (!item || typeof item !== 'object') continue;
            var fn = null;
            var t = String(item.title || '');
            var ic = String(item.pic_url || '').trim();
            var isSup = false;
            if (map[ic]) fn = map[ic];
            if (!fn) {
                if (t.indexOf('𝟏𝟐𝟑') > -1) fn = jdb3ExternalFix123av;
                else if (t.indexOf('𝐁𝐞𝐬𝐭𝐉𝐚𝐯') > -1) fn = jdb3ExternalFixBestjav;
                else if (t.indexOf('𝐗𝐒𝐙𝐀𝐕') > -1) fn = jdb3ExternalFixXszav;
                else if (t.indexOf('𝐉𝐚𝐯𝐆𝐮𝐫𝐮') > -1) fn = jdb3ExternalFixJavguru;
                else if (t.indexOf('𝐒𝐮𝐩𝐉𝐚𝐯') > -1 || /SupJav/i.test(t)) fn = jdb3ExternalFixSupjav;
            }
            if (fn === jdb3ExternalFixSupjav) isSup = true;
            if (!fn) continue;
            try {
                var nu = fn(code);
