        /* ---- 原版 base64 解码，带引擎函数缺失时的兜底 ---- */
        function b64Decode(text){
            text = String(text || '').replace(/[\r\n\t\s]/g, '');
            try{ if(typeof base64Decode === 'function') return base64Decode(text); }catch(e){}
            try{ if(typeof atob === 'function') return decodeURIComponent(escape(atob(text))); }catch(e){}
