            try{ if($ && typeof $.base64Decode === 'function') return $.base64Decode(text); }catch(e){}
            return '';
        }

        /* ---- 原版校验（不锁死单个版本号，兼容远程后续更新） ---- */
        function validCodeLazy(js){
            js = String(js || '');
            return js.indexOf('CodeLazyRemoteVersion:') > -1 &&
                   js.indexOf('CodeLazy') > -1 &&
                   (js.indexOf('normalizeLazyCode') > -1 || js.indexOf('123AV直连详情页') > -1);
        }

        /* ---- 原版 decodeCodeLazy：明文直接用，base64 包一层也能解 ---- */
        function decodeCodeLazy(raw){
            var text = String(raw || '').replace(/^\uFEFF/, '').trim();
            if (!text) return '';
            if (validCodeLazy(text)) return text;
            if (text.charAt(0) === '[' || text.charAt(0) === '{') {
                /* 引擎对 hiker://files 里的 js 可能带 json 包装，剥一层 */
                try{
                    var arr = JSON.parse(text);
                    if (arr && arr[0] && arr[0].content && validCodeLazy(arr[0].content)) return String(arr[0].content);
                }catch(e){}
            }
            try{
                var js = b64Decode(text).replace(/^\uFEFF/, '');
                if (validCodeLazy(js)) return js;
                if (js && js.charAt(0) === '[') {
                    try{
                        var arr2 = JSON.parse(js);
                        if (arr2 && arr2[0] && arr2[0].content && validCodeLazy(arr2[0].content)) return String(arr2[0].content);
                    }catch(e){}
                }
            }catch(e){}
            return '';
        }

        function readLocal(){
            try{ return fetch(CL_PATH) || ''; }catch(e){ return ''; }
        }

        /* ---- 原版 downcode()：远程拉取 → 解码 → writeFile 落地 → 再读本地 ----
           地址链：原版地址优先，拉不动再试同内容镜像（仍是远程拉取落地，不做内置静态） */
        function pullRemote(force){
            var sources = [CL_REMOTE, CL_MIRROR_1, CL_MIRROR_2];
            for (var si = 0; si < sources.length; si++) {
                try{
                    var remote = b64Decode(sources[si]);
                    if (!remote) continue;
                    var bust = (remote.indexOf('?') > -1 ? '&' : '?') + '_t=' + new Date().getTime();
