                    var back = readLocal();
                    var code = decodeCodeLazy(back) || js;
                    log('CodeLazy远程文件已更新：' + code.length + '字节');
                    return code;
                }catch(e){
                    log('CodeLazy远程更新失败：' + e);
                }
            }
            if (force) toast('CodeLazy远程内容为空或解码失败');
            return '';
        }

        /* ---- 原版 preRule 的按天刷新（跨天计数） ---- */
        function countCrossedDays(a, b){
            var d1 = new Date(Number(a)), d2 = new Date(Number(b));
            var s = new Date(d1.getFullYear(), d1.getMonth(), d1.getDate());
            var e = new Date(d2.getFullYear(), d2.getMonth(), d2.getDate());
            return Math.ceil(Math.abs(e - s) / (1000 * 60 * 60 * 24));
        }
        function needRefresh(){
            try{
                var now = new Date().getTime().toString();
                var last = String(getItem(CL_UPDATE_KEY, '0') || '0');
                if (!last || last === '0') return true;
                return countCrossedDays(now, last) >= CL_UPDATE_DAYS;
            }catch(e){ return false; }
        }
        function markRefresh(){
            try{ setItem(CL_UPDATE_KEY, new Date().getTime().toString()); }catch(e){}
        }

        /* ① 读本地 ② 解码 */
        var clCode = decodeCodeLazy(readLocal());

        /* ③ 本地没有 → 远程拉取落地；本地有 → 按天刷新（刷新失败保留本地旧版） */
        if (!clCode) {
            clCode = pullRemote(false);
            if (clCode) markRefresh();
        } else if (needRefresh()) {
            markRefresh();
            var fresh = pullRemote(false);
            if (fresh) clCode = fresh;
        }

        /* ④ eval 本地内容（直接 eval 取回 CodeLazy 函数，闭包保留模块作用域） */
        function evalCodeLazy(src){
            try{
                return eval(String(src) + '\n;typeof CodeLazy!=="undefined"?CodeLazy:null');
            }catch(e){
                log('CodeLazy eval失败：' + e);
                return null;
            }
        }

        var clFn = clCode ? evalCodeLazy(clCode) : null;

        /* ⑤ 本地内容读到了但 eval 失败 → 强制远程更新一次再试（原版同款兜底） */
        if (typeof clFn !== 'function' && clCode) {
            var again = pullRemote(true);
            if (again) clFn = evalCodeLazy(again);
        }
        if (typeof clFn !== 'function') { try{ if (typeof CodeLazy === 'function') clFn = CodeLazy; }catch(e){} }

        /* ⑥ 按番号渲染 10 个源 */
