let out=[],seen={},rows=[];
try{rows=pdfa(html,'.torrent-list&&tbody&&tr');}catch(e){}
if(!rows.length){try{rows=pdfa(html,'table.torrent-list&&tbody&&tr');}catch(e){}}
for(let i=0;i<rows.length;i++){
let row=rows[i],all='';
try{all=pdfh(row,'Text')||'';}catch(e){}
if(String(all).indexOf('置顶')>=0)continue;
let title='',mag='',size='',date='';
