try{mag=pdfh(row,'td:eq(2)&&a&&href')||'';}catch(e){}
try{size=pdfh(row,'td:eq(3)&&Text')||'';}catch(e){}
try{date=pdfh(row,'td:eq(4)&&Text')||'';}catch(e){}
