seen[mag]=1;
let tds=[],tm,tre=/<td\b[^>]*>([\s\S]*?)<\/td>/gi;
while((tm=tre.exec(row))!==null)tds.push(tm[1]);
let title=tds.length>1?txt(tds[1]):keyword;
