function probeDomain(list, path) {
    // 只试前两条、短超时：探不通就直接用列表第一条兜底，别把首屏拖死
    for (var i = 0; i < list.length && i < 2; i++) {
        try {
            var probe = JSON.parse(fetch(list[i] + (path || ''), { withStatusCode: true, timeout: 3500 }));
            if (probe.statusCode > 0) return list[i];
        } catch (e) { log('域名探测失败 ' + list[i]) }
    }
    return "";
}

