        switch (parseInt(tindex)) {
            case 0:
                eval(pageRule('home'))
                break;
            case 1:
                eval(pageRule('cla'))
                break;
            case 2:
                eval(pageRule('cla1'))
                break;
        }
        initOK = true;
    } catch (e) {
        initErr = e.message || String(e);
        log('初始化失败: ' + initErr)
    }
    if (initOK) {
        setItem('initFailAt', '0');
    } else {
        // 冷启动那一下最常见的就是请求空手而归：自动重来一次（120 秒内只自动试一次，不会死刷）
        var now = apiview.timestamp();
        var lastFail = parseInt(getItem('initFailAt') || '0') || 0;
        if (MY_PAGE == 1 && (now - lastFail > 120)) {
            setItem('initFailAt', String(now));
            bootstrapEnv(true);
            apiview.gettoken();
            toast('网络没跟上，自动重试…');
            refreshPage();
        } else {
            apiview.failRow(d, initErr);
        }
    }
} catch (e) {
    // 最外层兜底：页面构建真炸了也得给一句人话，别白屏
    log('页面构建失败: ' + (e.message || e))
    d.push({
        title: '页面出了点问题：' + (e.message || e) + '（下拉刷新一次）',
        url: 'hiker://empty',
        col_type: 'rich_text'
    })
}

setResult(d)

