        platform: "3",
        ip: "0.0.0.0",
        signSuffix: "m4n2hjPeYWkD6tFpqKF^3HO^h24P@idT"
    },
    apiHost: () => {
        var host = getItem("api");
        if (!host) {
            host = getItem("apiCache") || apiview.apiFallback[0];
            setItem("api", host);
        }
        return host;
    },
    apiFallback: ["https://api.em1oifd0.com", "https://api.61c76a0.com", "https://api.87735d5.com", "https://api.c6dd5cc.com", "https://api.j7y675.com"],
    apiList: () => {
        var list = [];
        var cur = getItem("api");
        var cached = [];
        try { cached = JSON.parse(getItem("apiList") || "[]") } catch (e) { cached = [] }
        if (cur) list.push(cur);
        (cached.length ? cached : apiview.apiFallback).forEach(h => { if (h && list.indexOf(h) < 0) list.push(h) });
        apiview.apiFallback.forEach(h => { if (h && list.indexOf(h) < 0) list.push(h) });
        return list;
    },
    setApi: (h) => {
        if (!h) return;
        setItem("api", h);
        setItem("apiCache", h);
    },
    imageHost: () => {
        var host = getItem("imgDomain");
        if (host) return host;
        var list = [];
        try { list = JSON.parse(getItem("imgDomainList") || "[]") } catch (e) { list = [] }
        if (list.length) {
            setItem("imgDomain", list[0]);
            return list[0];
        }
        return "";
    },
    // 播放地址：域名探测失败时用缓存里的第一个，别把半截相对路径丢给播放器
    vodUrl: (path) => {
        if (!path) return "";
        if (String(path).indexOf("http") === 0) return path;
        var host = getItem("vodDomain");
        if (!host) {
            var list = [];
            try { list = JSON.parse(getItem("vodList") || "[]") } catch (e) { list = [] }
            host = list.length ? list[0] : "";
            if (host) setItem("vodDomain", host);
        }
        return host + path;
    },
    // ---------- 封面工具：字段名不挑、结构不挑，尽量把图挖出来 ----------
    imgKeys: ["thumb", "thumbnail", "cover", "cover_url", "coverUrl", "thumb_url", "thumbnail_url", "poster", "poster_url", "pic", "pics", "pic_url", "picUrl", "image", "image_url", "img", "img_url", "imgUrl", "photo", "preview", "preview_pic", "previewPic", "first_pic", "firstPic", "latest_pic", "latestPic", "vertical", "vertical_thumb", "horizontal", "horizontal_thumb", "src", "path", "url"],
    isImgPath: (s) => {
        if (typeof s !== "string") return false;
        var t = s.replace(/^\s+|\s+$/g, "");
        if (t.length < 5 || t.indexOf(" ") >= 0) return false;
        if (/\.(mp4|m3u8|mp3|m4a|aac|wav|flac|ts|mkv|avi|mov|zip|apk|txt|json|html?)(\?|#|$)/i.test(t)) return false;
        if (/\.(jpg|jpeg|png|webp|gif|bmp|avif)(\?|#|$)/i.test(t)) return true;
        if (t.indexOf("http") === 0 || t.indexOf("//") === 0) {
            // 无后缀的 CDN 图靠路径关键词认，别把接口链接当封面
            return /(image|img|thumb|photo|pic|cover|poster|upload|storage|media|static|cdn)/i.test(t);
        }
        if (t.charAt(0) === "/") return true;
        return false;
    },
    maybeCipher: (s) => {
        if (typeof s !== "string") return false;
        var t = s.replace(/^\s+|\s+$/g, "");
        if (t.length < 12 || t.length > 400) return false;
        if (t.indexOf(" ") >= 0 || t.indexOf("http") === 0) return false;
        if (/\.(jpg|jpeg|png|webp|mp4|m3u8|html?|json)(\?|#|$)/i.test(t)) return false;
        return /^[A-Za-z0-9+\/=\-_]+$/.test(t);
    },
    pickImgPath: (o, depth, box) => {
        var dep = depth || 0;
        var b = box || { weak: "" };
        if (dep > 3 || o === null || o === undefined) return "";
        if (typeof o === "string") {
            if (apiview.isImgPath(o)) return o;
            if (!b.weak && apiview.maybeCipher(o)) b.weak = o;
            return "";
        }
        if (typeof o !== "object") return "";
        if (o instanceof Array) {
            for (var i = 0; i < o.length; i++) {
                var ra = apiview.pickImgPath(o[i], dep + 1, b);
                if (ra) return ra;
            }
            return "";
        }
        // 1) 先按已知封面字段名找，命中率最高
        for (var k = 0; k < apiview.imgKeys.length; k++) {
            var key = apiview.imgKeys[k];
            if (!(key in o)) continue;
            var v = o[key];
            if (typeof v === "string") {
                if (apiview.isImgPath(v)) return v;
                if (!b.weak && apiview.maybeCipher(v)) b.weak = v;
                continue;
            }
            var rv = apiview.pickImgPath(v, dep + 1, b);
            if (rv) return rv;
        }
        // 2) 再全字段扫一遍（只认明确的图，免得把 id/时间戳当封面）
        for (var kk in o) {
            if (apiview.imgKeys.indexOf(kk) >= 0) continue;
            var r2 = apiview.pickImgPath(o[kk], dep + 1, { weak: "" });
            if (r2) return r2;
        }
        return "";
    },
    // 封面：字段兜底 + 结构兜底；相对路径才走解密管道
    imgUrl: (path, fallback) => {
        var p = "";
        var box = { weak: "" };
        if (path && typeof path === "object") p = apiview.pickImgPath(path, 0, box);
        else if (typeof path === "string") p = path;
        if (!p && box.weak) p = box.weak;
        if (!p && fallback) p = (typeof fallback === "string") ? fallback : apiview.pickImgPath(fallback, 0);
        if (!p) return "https://img.vinua.cn/images/InnDk.th.png";
        if (p.indexOf("//") === 0) return "https:" + p;
        if (p.indexOf("http") === 0) return p;
        var host = apiview.imageHost();
        if (!host) return p;
        if (host.charAt(host.length - 1) !== "/" && p.charAt(0) !== "/") host = host + "/";
        return apiview.Decrypt1(host + p);
    },
    // 正文大图：接口正文里塞的都是 _thumbnail 小图(800px)，去掉后缀才是原图(1200~2560px)
    bigPic: (p) => {
        if (!p || typeof p !== "string") return p;
        return p.replace(/_thumbnail(\.[A-Za-z0-9]+)$/i, "$1");
    },
    // 视频源：h265 → hls → mp4 → 老字段，跳过音频与占位片
    pickVideo: (data) => {
        if (!data) return "";
        var chain = [data.video_hls_h265, data.video_hls, data.video_file, data.video];
        for (var i = 0; i < chain.length; i++) {
            var v = chain[i];
            if (typeof v === "string" && v.length > 4) {
                if (/\.(mp3|m4a|aac|wav|flac)(\?|$)/i.test(v)) continue;
                if (/onefxxku0326/.test(v)) continue; // 站点占位广告片，别当正片
                return v;
            }
        }
        return "";
    },
    pickAudio: (data) => {
        if (!data) return "";
        var chain = [data.audio_hls, data.audio_file, data.video];
        for (var i = 0; i < chain.length; i++) {
            var v = chain[i];
            if (typeof v === "string" && v.length > 4) return v;
        }
        return "";
    },
    signHeaders: (token, host) => {
        var ids = apiview.ids;
        var t10 = apiview.t10();
        var first = md5(ids.ip + "." + ids.platform + "." + t10 + "." + ids.userKey + "." + ids.uuid);
        host = host || apiview.apiHost();
        return {
            "uuid": ids.uuid,
            "timestamp": t10,
            "ip": ids.ip,
            "user-key": ids.userKey,
            "platform": ids.platform,
            "sign": md5(first + ids.signSuffix),
            "app-version": ids.appVersion,
            "token": token === undefined ? (getItem("token") || "") : token,
            "Content-Type": "application/x-www-form-urlencoded",
            "Connection": "Keep-Alive",
            "Host": host.split("//")[1] || "",
            "User-Agent": "okhttp/5.0.0-alpha.11"
        };
    },
    // ---------- 合集：不挑接口、不挑字段名，能返回多少集就吃多少集 ----------
    seriesIdOf: (data) => {
        if (!data || typeof data !== "object") return 0;
        var keys = ["series_id", "seriesId", "series", "collection_id", "collectionId", "album_id", "manga_id", "group_id"];
        for (var i = 0; i < keys.length; i++) {
            if (!(keys[i] in data)) continue;
            var v = data[keys[i]];
            if (v === undefined || v === null || v === "") continue;
            if (typeof v === "object") {
                if (v instanceof Array) continue;
                var inner = v.id || v.series_id || v.seriesId;
                if (inner) return inner;
                continue;
            }
            var n = parseInt(v);
            if (n) return n;
        }
        return 0;
    },
    chapterId: (c) => {
        if (!c || typeof c !== "object") return "";
        var keys = ["id", "article_id", "contents_id", "content_id"];
        for (var i = 0; i < keys.length; i++) {
            var v = c[keys[i]];
            if (v !== undefined && v !== null && v !== "") return v;
        }
        return "";
    },
    pickTotal: (data) => {
        if (!data || typeof data !== "object") return 0;
        var keys = ["total", "count", "total_count", "totalCount", "chapter_count", "chapterCount", "num"];
        for (var i = 0; i < keys.length; i++) {
            var v = parseInt(data[keys[i]]);
            if (v > 0) return v;
        }
        var sub = data.pagination || data.meta || data.page;
        if (sub && typeof sub === "object") return apiview.pickTotal(sub);
        return 0;
    },
    // 从任意结构里挖章节数组：认「有 id 且有 chapter/title」的对象数组，取最长的一组
    pickChapters: (obj, strict) => {
        var best = [];
        var ok = (arr) => {
            if (!(arr instanceof Array) || !arr.length) return false;
            var hit = 0;
            for (var i = 0; i < arr.length && i < 5; i++) {
                var it = arr[i];
                if (!it || typeof it !== "object" || it instanceof Array) return false;
                if (it.id === undefined && it.article_id === undefined && it.contents_id === undefined) continue;
                if (it.chapter !== undefined || it.episode !== undefined) hit++;
                else if (!strict && it.title !== undefined) hit++;
            }
            return hit > 0;
        };
        var walk = (o, dep) => {
            if (dep > 3 || !o || typeof o !== "object") return;
            if (o instanceof Array) {
                if (ok(o)) {
                    if (o.length > best.length) best = o;
                    return;
                }
                for (var i = 0; i < o.length && i < 20; i++) walk(o[i], dep + 1);
                return;
            }
            for (var k in o) walk(o[k], dep + 1);
        };
        walk(obj, 0);
        return best;
    },
    normalizeSeries: (data, sid, strict) => {
        if (!data || typeof data !== "object") return null;
        if (data instanceof Array) data = { chapters: data };
        var chapters = apiview.pickChapters(data, strict);
        if (!chapters.length) return null;
        var s = data.series || data.series_info || data.seriesInfo || data.collection;
        if (s && typeof s === "object" && !(s instanceof Array)) {
            var c2 = apiview.pickChapters(s, strict);
            if (c2.length > chapters.length) chapters = c2;
        }
        var meta = (s && typeof s === "object" && !(s instanceof Array)) ? s : data;
        return {
            id: sid || data.series_id || data.seriesId || data.id || "",
            title: data.title || data.name || meta.title || meta.name || "",
            author: data.author || data.actor || meta.author || meta.actor || "",
            thumb: apiview.pickImgPath(data, 0, { weak: "" }) || "",
            total: apiview.pickTotal(data) || apiview.pickTotal(meta),
            chapters: chapters
        };
    },
    fetchSeries: (path, sid) => {
        var url = apiview.apiHost() + path;
        var bodies = ["series_id=" + sid + "&page=1&size=500", "series_id=" + sid];
        for (var b = 0; b < bodies.length; b++) {
            var data = null;
            try {
                var res = JSON.parse(apiview.gethtml(url, apiview.Encrypt(bodies[b])));
                data = res && res.data;
            } catch (e) {
                log("合集取数失败 " + path + ": " + e.message);
                continue;
            }
            if (!data) continue;
            var info = apiview.normalizeSeries(data, sid);
            if (!info || !info.chapters.length) continue;
            // 只回了一页的，按 total 把后面几页补上，别只显示一集
            var total = info.total || 0;
            if (total > info.chapters.length) {
                var seen = {};
                info.chapters.forEach((c) => { seen[String(apiview.chapterId(c))] = 1 });
                for (var pg = 2; pg <= 20 && info.chapters.length < total; pg++) {
                    var more = null;
                    try {
                        var r2 = JSON.parse(apiview.gethtml(url, apiview.Encrypt("series_id=" + sid + "&page=" + pg + "&size=500")));
                        more = apiview.pickChapters(r2 && r2.data);
                    } catch (e2) { break }
                    if (!more || !more.length) break;
                    var added = 0;
                    more.forEach((c) => {
                        var cid = String(apiview.chapterId(c));
                        if (cid && !seen[cid]) { seen[cid] = 1; info.chapters.push(c); added++ }
                    });
                    if (!added) break;
                }
            }
            return info;
        }
        return null;
    },
    seriesInfo: (seriesId) => {
        var inline = null;
        if (seriesId && typeof seriesId === "object") {
            var sidIn = apiview.seriesIdOf(seriesId);
            inline = apiview.normalizeSeries(seriesId, sidIn, true);
            seriesId = sidIn;
        }
        var sid = parseInt(seriesId || 0);
        if (!sid) return inline;
        var paths = ["/v2.5/series/chapters", "/v2.5/series/detail", "/v2.5/series/info"];
        for (var i = 0; i < paths.length; i++) {
            var info = apiview.fetchSeries(paths[i], sid);
            if (info && info.chapters.length) {
                if (inline && inline.chapters.length > info.chapters.length) return inline;
                return info;
            }
        }
        return inline;
    },
    // 合集选集卡片：默认先渲染 30 集，超出给「加载更多」，几百集的合集也不会卡
    chapterCards: (d, info, sid, currentId) => {
        var all = (info && info.chapters) || [];
        if (!all.length) return;
        var batchKey = "cb_" + String(sid);
        var batch = parseInt(getMyVar(batchKey, "30")) || 30;
        if (batch < 1) batch = 30;
        var moreUrl = "";
        if (all.length > batch) {
            try {
                moreUrl = $('#noLoading#').lazyRule((batchKey, batch) => {
                    putMyVar(batchKey, String(parseInt(batch) + 60))
                    refreshPage()
                    return 'hiker://empty'
                }, batchKey, String(batch));
            } catch (e) {
                log("加载更多按钮生成失败: " + e.message);
                moreUrl = "";
            }
            // 按钮拿不到就不分批了，一次渲染完，免得既没按钮又缺内容
            if (!moreUrl) batch = all.length;
        }
        var list = all.slice(0, Math.min(batch, all.length));
        var cover = apiview.imgUrl(info.thumb);
        list.forEach((c, i) => {
            try {
                var cimg = apiview.imgUrl(c, cover);
                var cur = currentId !== undefined && currentId !== null && String(apiview.chapterId(c)) == String(currentId);
                d.push({
                    title: (cur ? "\u25b6 " : "") + "第" + (c.chapter || (i + 1)) + "集\t" + (c.title || ""),
                    desc: (c.published_at || "").split(" ")[0],
                    img: cimg,
                    url: "hiker://page/erji?page=fypage#noHistory##gameTheme#",
                    col_type: "movie_1_left_pic",
                    extra: { model_id: "0", id: String(apiview.chapterId(c)), img: cimg }
                })
            } catch (e) {
                log("选集卡片渲染失败: " + e.message)
            }
        })
        if (moreUrl) {
            d.push({
                title: "⬇ 加载更多（已显示 " + list.length + " / 共 " + all.length + " 集）",
                url: moreUrl,
                col_type: 'text_center_1'
            })
        }
    },
    // 在详情页渲染「合集」区块：封面 + 共几集 + 每集卡片
    seriesBlock: (d, data) => {
        var info = apiview.seriesInfo(data);
        if (!info || !info.chapters || !info.chapters.length) return false;
        var cover = apiview.imgUrl(info.thumb || info.chapters[0]);
        var sid = info.id || apiview.seriesIdOf(data);
        var curId = (data && data.id !== undefined && data.id !== null) ? data.id : apiview.chapterId(data);
        var idx = -1;
        info.chapters.forEach((c, i) => { if (String(apiview.chapterId(c)) == String(curId)) idx = i });
        // 当前集在后面时，先把批次撑到它，免得"当前集"看不到
        if (idx >= 0) {
            var batchKey = "cb_" + String(sid);
            var batch = parseInt(getMyVar(batchKey, "30")) || 30;
            if (idx + 1 > batch) putMyVar(batchKey, String(idx + 31));
        }
        d.push({
            title: "📚 " + (info.title || "合集") + "\t共 " + info.chapters.length + " 集",
            desc: (info.author || "ONE 编辑部") + (idx >= 0 ? "｜第 " + (idx + 1) + " 集" : ""),
            img: cover,
            url: "hiker://empty",
            col_type: "movie_1_left_pic",
            extra: { pageTitle: info.title || "合集" }
        })
        var prev = (idx > 0) ? info.chapters[idx - 1] : null;
        var next = (idx >= 0 && idx < info.chapters.length - 1) ? info.chapters[idx + 1] : null;
        if (prev || next) {
            if (prev) {
                d.push({
                    title: "◀ 上一集",
                    url: "hiker://page/erji?page=fypage#noHistory##gameTheme#",
                    col_type: "flex_button",
                    extra: { model_id: "0", id: String(apiview.chapterId(prev)), img: apiview.imgUrl(prev, cover) }
                })
            }
            if (next) {
                d.push({
                    title: "▶ 下一集",
                    url: "hiker://page/erji?page=fypage#noHistory##gameTheme#",
                    col_type: "flex_button",
                    extra: { model_id: "0", id: String(apiview.chapterId(next)), img: apiview.imgUrl(next, cover) }
                })
            }
        }
        d.push({
            title: apiview.big(apiview.strong("〖 本合集选集 〗")),
            url: "hiker://empty",
            col_type: "rich_text"
        })
        apiview.chapterCards(d, info, sid, curId);
        return true;
    },
    // 合集（系列）总览：给「写真 / 漫画」列表点进去用
    seriesChapterList: (seriesId) => {
        var info = apiview.seriesInfo(seriesId);
        if (!info) return [];
        return info.chapters.map((c, i) => ({
            id: apiview.chapterId(c),
            title: c.title || ("第" + (c.chapter || i + 1) + "集"),
            chapter: c.chapter || (i + 1),
            img: apiview.imgUrl(c.thumb || c.thumbnail, info.thumb),
            published_at: (c.published_at || "").split(" ")[0],
            cover: apiview.imgUrl(info.thumb)
        }))
    },
    timestamp: () => Math.floor(new Date().getTime() / 1000),
    t10: () => apiview.timestamp().toString(),
    t13: () => apiview.t10() + '000',
    host: getItem("api"),
    getDatesArray: (endDate) => {
        // 将结束日期字符串转换为Date对象
        let endDateObj = new Date(endDate);

        // 获取当前日期
        let currentDate = new Date();

        // 初始化日期数组
        let datesArray = [];

        // 循环从当前日期到结束日期
        while (currentDate >= endDateObj) {
            // 将日期转换为YYYY-MM-DD格式的字符串并添加到数组
            datesArray.push(currentDate.toISOString().split('T')[0]);

            // 减去一天
            currentDate.setDate(currentDate.getDate() - 1);
        }
        /*
            // 反转数组以按降序排列日期
            datesArray.reverse();
        */
        return datesArray;
    },
    getYearMonthArray: (endDate) => {
        let endDateObj = new Date(endDate);
        let currentDate = new Date();
        let yearMonthArray = [];

        // 确保当前日期不小于结束日期
        if (currentDate < endDateObj) {
            return yearMonthArray; // 如果当前日期小于结束日期，直接返回空数组
        }

        // 循环从当前日期到结束日期
        while (currentDate >= endDateObj) {
            // 获取当前日期的年和月，并格式化为"YYYY-MM"字符串
            let year = currentDate.getFullYear();
            let month = (currentDate.getMonth() + 1).toString().padStart(2, '0'); // 月份从0开始，所以加1，并且确保是两位数
            let yearMonth = `${year}-${month}`; // 正确使用模板字符串

            // 将年月字符串添加到数组
            yearMonthArray.push(yearMonth);

            // 减去一个月
            currentDate.setMonth(currentDate.getMonth() - 1);
        }

        return yearMonthArray;
    },
    CryptoJS: null, // 用于存储 CryptoJS 对象
    initCryptoJS: () => {
        if (!apiview.CryptoJS) {
            eval(getCryptoJS()); // 执行一次 eval，确保 `CryptoJS` 变量被定义
            apiview.CryptoJS = CryptoJS; // 将 `CryptoJS` 缓存到 `apiview.CryptoJS`
        }
    },
    Encrypt: (word) => {
        apiview.initCryptoJS(); // 确保 CryptoJS 已加载
        let key = apiview.CryptoJS.enc.Utf8.parse("l*bv%Ziq000Biaog");
        let iv = apiview.CryptoJS.enc.Utf8.parse("8597506002939249");
        let encrypt = apiview.CryptoJS.AES.encrypt(word, key, {
            iv: iv,
            mode: apiview.CryptoJS.mode.CBC,
            padding: apiview.CryptoJS.pad.Pkcs7,
        });
        return encrypt.toString(); // 默认返回 Base64 编码的字符串
    },
    Decrypt: (word) => {
        apiview.initCryptoJS(); // 确保 CryptoJS 已加载
        let key = apiview.CryptoJS.enc.Utf8.parse("l*bv%Ziq000Biaog");
        let iv = apiview.CryptoJS.enc.Utf8.parse("8597506002939249");
        let decrypt = apiview.CryptoJS.AES.decrypt(word, key, {
            iv: iv,
            mode: apiview.CryptoJS.mode.CBC,
            padding: apiview.CryptoJS.pad.Pkcs7,
        });
        return decrypt.toString(apiview.CryptoJS.enc.Utf8); // 解密结果转换为文本格式
    },
    Decrypt1: (input) => {
        return $(input).image(() => {
            const CryptoUtil = $.require("hiker://assets/crypto-java.js");
            let key = CryptoUtil.Data.parseUTF8("saIZXc4yMvq0Iz56");
            let iv = CryptoUtil.Data.parseUTF8("kbJYtBJUECT0oyjo");
            let textData = CryptoUtil.Data.parseInputStream(input);
            let encrypted = CryptoUtil.AES.decrypt(textData, key, {
                mode: "AES/CBC/PKCS7Padding",
                iv: iv
            });
            return encrypted.toInputStream();
        })
    },
    // 取 token：域名逐个试，全失败就拿上一次缓存的 token 顶上
    gettoken: () => {
        var token = "";
        var hosts = apiview.apiList();
        for (var i = 0; i < hosts.length && !token; i++) {
            try {
                var html = fetch(hosts[i] + "/v2.5/refresh/token", {
                    headers: apiview.signHeaders("", hosts[i]),
                    method: "POST",
                    rejectCoding: true,
                    timeout: 7000
                });
                html = (html === null || html === undefined) ? "" : String(html);
                if (!html.trim()) { log("取 token 空响应: " + hosts[i]); continue }
                token = JSON.parse(apiview.Decrypt(html)).data.user.token;
                if (i > 0) apiview.setApi(hosts[i]);
            } catch (e) {
                log("取 token 失败 " + hosts[i] + ": " + e.message)
            }
        }
        if (!token) token = getItem("tokenCache") || getItem("token") || "";
        if (token && token != "undefined") {
            setItem("token", token);
            setItem("tokenCache", token);
            return token;
        }
        return "";
    },
    // 底层请求：空响应 / 失败自动换域名重来，绝不把空串丢给 JSON.parse
    getRaw: (url, body) => {
        var path = String(url).replace(/^https?:\/\/[^\/]+/, "");
        var hosts = apiview.apiList();
        var token = getItem("token") || "";
        var last = "空响应";
        for (var round = 0; round < 2; round++) {
            var list = round === 0 ? [hosts[0]] : hosts.slice(1, 4);
            for (var i = 0; i < list.length; i++) {
                try {
                    var html = fetch(list[i] + path, {
                        headers: apiview.signHeaders(token, list[i]),
                        body: body,
                        method: "POST",
                        rejectCoding: true,
                        timeout: 9000
                    });
                    html = (html === null || html === undefined) ? "" : String(html);
                    if (html.trim()) {
                        if (list[i] !== hosts[0]) apiview.setApi(list[i]);
                        return html;
                    }
                    log("空响应: " + list[i] + path);
                } catch (e) {
                    last = e.message;
                    log("请求失败 " + list[i] + path + " -> " + e.message)
                }
            }
            if (round === 0) token = apiview.gettoken();
        }
        throw new Error("网络没响应（" + last + "）");
    },
    gethtml: (url, body) => {
        var html = apiview.getRaw(url, body);
        var plain = "";
        try {
            return apiview.Decrypt(html);
        } catch (e) {
            // 拿到的不是密文（多半是 401 明文），换新 token 再走一遍
            plain = String(html || "").slice(0, 80);
            log("首次解密失败，刷新 token 重试: " + e.message)
            var fresh = apiview.gettoken();
            if (fresh) {
                try { return apiview.Decrypt(apiview.getRaw(url, body)) } catch (e2) { log("换 token 后仍失败: " + e2.message) }
            }
            // 服务端在明文里说了话就直接翻译出来，别甩 Malformed UTF-8 这种看不懂的
            var m = plain.match(/"message"\s*:\s*"([^"]+)"/);
            if (m) throw new Error(m[1]);
            throw new Error("接口返回异常（收到的不是正常数据）");
        }
    },
    // 统一取数入口：空内容 / 接口报错都给一句人话，不裸解析
    getData: (url, body, label) => {
        var name = label || "接口";
        var txt = apiview.gethtml(url, body);
        txt = (txt === null || txt === undefined) ? "" : String(txt);
        if (!txt.trim()) throw new Error(name + "没回内容（空响应）");
        var res;
        try { res = JSON.parse(txt) } catch (e) { throw new Error(name + "返回的不是 JSON：" + txt.slice(0, 50)) }
        if (res && res.code && parseInt(res.code) != 200) {
            throw new Error(name + "报错 " + res.code + "：" + (res.message || ""));
        }
        return res;
    },
    // 失败兜底：一句人话 + 一个能点的重试，而不是干巴巴一行报错
    failRow: (d, msg) => {
        d.push({
            title: apiview.big(apiview.strong("这次没拉到数据")) + "<br>" + apiview.gray(msg || "网络没响应"),
            url: "hiker://empty",
            col_type: "rich_text"
        });
        d.push({
            title: "⟳ 点我重试",
            url: $("#noLoading#").lazyRule(() => {
                setItem("initFailAt", "0");
                refreshPage();
                return "hiker://empty"
            }),
            col_type: "text_center_1"
        });
        d.push({
            title: apiview.gray("连着不行就是当前线路挂了，过会儿再试"),
            url: "hiker://empty",
            col_type: "rich_text"
        });
    },
    tuwenyiji: (d, data) => {
        data.forEach(item => {
            var img = apiview.imgUrl(item)
            d.push({
                title: item.published_at.split(' ')[0],
