                        apiview.chapterCards(d, info, sid);
                    } catch (e) {
                        d = [{ title: apiview.gray("合集加载出错了：" + e.message + "，点这里重试"), url: MY_URL, col_type: "rich_text" }];
                    }
                    setResult(d)
                }),
