    // 正文：图集按原图整张铺开，文字段落按富文本走
    tuwen: (d, data) => {
        var content = data && data.content;
        if (!content || typeof content !== "string") return;
        var srcOf = (html) => {
            var src = "";
            try { src = pdfh(html, "img&&src") } catch (e) { src = "" }
            if (!src) {
                var m = String(html).match(/<img[^>]+src\s*=\s*["']([^"']+)["']/i);
                if (m) src = m[1];
            }
            return src;
        };
        var pushPic = (src) => {
            if (!src) return;
            var img = "";
            try { img = apiview.imgUrl(apiview.bigPic(src)) } catch (e) { img = "" }
            if (!img) return;
            d.push({
                img: img,
                url: img,
                col_type: 'pic_1_full'
            });
        };
        var imgs = content.replace(/(<figure[\S\s]*?<\/figure>)/g, "@$1@");
        imgs.split("@").forEach(it => {
            try {
                if (it.indexOf("figure") >= 0) {
                    pushPic(srcOf(it));
                } else if (it.trim()) {
                    d.push({
                        title: it.trim(),
                        url: 'hiker://empty',
                        col_type: 'rich_text'
                    });
                }
            } catch (e) {
                log('正文单条渲染失败: ' + e.message)
            }
        });
    },
    biaoqian: (d, data) => {
        var tags = (data && data.tags) || [];
        if (!tags.length) return;
        tags.forEach(item => {
            d.push({
                title: item,
                url: $(item + '#noLoading#').lazyRule(() => {
                    return 'hiker://empty'
                }),
                col_type: 'flex_button'
            })
        })
    },
    yulantu: (d, data) => {
        var pics = (data && data.multiple_pic) || [];
        if (!pics.length) return;
        pics.forEach(item => {
            let img = apiview.imgUrl(item);
            d.push({
                img: img,
                url: img,
                col_type: 'card_pic_3'
            })
        })
    },
    pinglun: (d, data) => {
