                var title = row.text + apiview.addressTag('hiker://page/pinlun', '\t\t\t查看全部')
            } else {
                var title = row.text
            }
            d.push({
                title: apiview.gray(title),
                col_type: 'rich_text',
                extra: {
                    title: row.author,
                    desc: row.created_at,
                    desc1: row.text,
                    img: avatar,
                    item: replies,
                    pageTitle: row.author
                }
            })
        })
    }

