        url: $('#noLoading#').lazyRule(()=>{
            clearMyVar('a')
            refreshPage()
            return 'hiker://empty'
        }),
        col_type: 'flex_button',
    })
    d.push({
        title: title2,
        url: $('#noLoading#').lazyRule(()=>{
            putMyVar('a','1')
            refreshPage()
            return 'hiker://empty'
        }),
        col_type: 'flex_button',
    })

    var hasPlay = !!(video || audio || data.preview_video);
    // 正文自带图（图集/图文）的，选集一律沉底，别把图顶到几十屏外面
    var hasFigures = typeof data.content === 'string' && data.content.indexOf('<figure') >= 0;
    var setBottom = !hasPlay || hasFigures;

