            url: apiview.vodUrl(data.preview_video),
            col_type: 'text_2',
        })
    }
    if(!video && audio){
        d.push({
            title: '\t\t\t\t\t\t\t\t\t🎧 播放音频\t\t\t\t\t\t\t\t\t',
            url: apiview.vodUrl(audio),
            col_type: 'text_2',
        })
    }
    if(!video && !audio && !data.preview_video){
        d.push({
            title: apiview.gray('这条没有正片源（图文/图集类）'),
            url: 'hiker://empty',
            col_type: 'text_center_1',
        })
    }
    // 纯看片的：选集紧跟播放按钮；其余选集沉底、正文先出
    if(hasPlay && !setBottom){
        try{ apiview.seriesBlock(d, data) }catch(e){ log('合集渲染失败: ' + e.message) }
    }
    d.push({
        title: apiview.big(apiview.strong(data.title || ''))+'<br><br>'+'番号：'+apiview.gray(data.number || '-')+'\t\t\t'+'演员：'+apiview.gray(data.actor || '-')+'<br>'+apiview.gray((data.published_at || '').split(' ')[0])+'\t\t\t'+apiview.gray(data.length || '')+'\t\t\t'+apiview.gray(data.size || '')+'\t\t\t'+apiview.gray(data.quality || ''),
        url: 'hiker://empty',
        col_type: 'rich_text'
    })
    try{ apiview.tuwen(d,data) }catch(e){ log('正文渲染失败: ' + e.message) }
    try{ apiview.biaoqian(d,data) }catch(e){ log('标签渲染失败: ' + e.message) }
    try{ apiview.yulantu(d,data) }catch(e){ log('预览图渲染失败: ' + e.message) }
    if(setBottom){
        try{ apiview.seriesBlock(d, data) }catch(e){ log('合集渲染失败: ' + e.message) }
    }
}
