var apiview = $.require("hanshu")
var model_id = MY_PARAMS.model_id; //log(typeof model_id)
var id = MY_PARAMS.id; //log(id)
var img = MY_PARAMS.img
var d = [];

if(MY_PAGE == '1'){
var data = null;
var derr = '';
try{
    var url = apiview.apiHost() + '/v2.5/article/detail'
    data = apiview.getData(url, apiview.Encrypt('id=' + id), '详情').data;
}catch(e){
    derr = e.message;
    log('详情拉取失败: ' + e.message)
}
if(!data){
    apiview.failRow(d, derr || '详情接口没回数据')
}else{
    // 以「详情接口自己报的类型」为准，列表传进来的只作兜底 —— 合集里混装条目全靠这个不出错
    var mid = parseInt(data.model_id || model_id || 0);
    var cover = apiview.imgUrl(data, img);
    var video = apiview.pickVideo(data);
    var audio = apiview.pickAudio(data);
    // 有没有正片源：有源的是看片，没源的是看内容
    var hasPlay = !!(video || audio || data.preview_video);
    // 正文自带图（图文/图集/漫画）的，选集一律沉底，别把图顶到几十屏外面去
    var hasFigures = typeof data.content === 'string' && data.content.indexOf('<figure') >= 0;
    var setBottom = !hasPlay || hasFigures;

    // 正文类先亮标题，点进来一眼知道这是啥
    if(!hasPlay){
        d.push({
            title: apiview.big(apiview.strong(data.title || '')) + (data.author ? '<br>' + apiview.gray(data.author) : ''),
            url: 'hiker://empty',
            col_type: 'rich_text'
        })
    }

    if(mid != 2 && cover){
        d.push({
            img: cover,
            url: cover,
            col_type: 'pic_1_full'
        })
    }

    if(hasPlay){
        if(video){
            d.push({
                title: '““▶ 播放正片””',
                url: apiview.vodUrl(video),
                col_type: 'text_center_1'
            })
        }
        if(data.preview_video){
            d.push({
                title: apiview.gray('““片花预览””'),
                url: apiview.vodUrl(data.preview_video),
                col_type: 'text_center_1'
            })
        }
        if(!video && audio){
            d.push({
                title: '““🎧 播放音频””',
                url: apiview.vodUrl(audio),
                col_type: 'text_center_1'
            })
        }
        d.push({
            title: apiview.big(apiview.strong(data.title || '')) + '<br>' + apiview.gray(data.author || '') + '<br>' + apiview.gray(data.description || ''),
            url: 'hiker://empty',
            col_type: 'rich_text'
        })
        // 纯看片的：选集紧跟着播放按钮
        if(!setBottom){ try{ apiview.seriesBlock(d, data) }catch(e){ log('合集渲染失败: ' + e.message) } }
    }

    // 正文图集/文字：紧跟封面出图，不再被几十张选集卡片顶到屏幕外面去
    try{ apiview.tuwen(d, data) }catch(e){ log('正文渲染失败: ' + e.message) }
    try{ apiview.biaoqian(d,data) }catch(e){ log('标签渲染失败: ' + e.message) }
    try{ apiview.yulantu(d,data) }catch(e){ log('预览图渲染失败: ' + e.message) }

    if(setBottom){
        // 看内容的（或正文带图的）：选集挪到底部，先看图再翻集
        try{ apiview.seriesBlock(d, data) }catch(e){ log('合集渲染失败: ' + e.message) }
    }
}
}

