              putMyVar("MissAV.subCate", index.toString())
              refreshPage(true)
              return "hiker://empty"
            }, index),
            col_type: 'scroll_button',
          })
        })
      }
    }

    const html = fetch(url, {headers:{'User-Agent': 'Mozilla/5.0 (Windows NT 10.0)'}})

    switch (type) {
      case 'video':
        miss.videoType(html)
        break
      case 'articles':
        miss.articlesType(html)
        break
      case 'avatar':
