pages.rule:
function getConfig() {
    try {
        let config = fetch("hiker://files/rules/ApolloImg/config.json");
        if (!config || config == "") {
            return {
                data: [],
                version: 0
            }
        } else {
            return JSON.parse(config)
        }
    } catch (e) {
        try {
            toast("配置文件格式有误")
        } catch (e) {}
        return {
            data: [],
            version: 0
        }
    }
}

function batchImport(input, rule) {
    input = input.trim();
    if (input.length < 3 || input[0] != "{") {
        return "toast://请输入正确的格式"
    }
    let im = JSON.parse(input);
    if (im.data == null || im.data.length < 1) {
        return "toast://请输入正确的格式"
    }
    eval(JSON.parse(request("hiker://page/config?rule=" + rule)).rule);
    let config = getConfig();
    let count = 0;
    let all = config.data.map(it => it.url + "&&&").join();
    for (let i of im.data) {
        if (all.indexOf(i.url + "&&&") >= 0) {
            //重复的不要
            continue;
        }
        count++;
        config.data.push(i)
    }
    writeFile("hiker://files/rules/ApolloImg/config.json", JSON.stringify(config));
    refreshPage();
    return "toast://已导入" + count + "条订阅源";
}

function renderLiveData(url,ua) {
    let m3u = "";
    if (url.startsWith('hiker://') || url.startsWith('file://')) {
        m3u = fetch(url);
    } else {
        let interval = Number(getItem('interval', '24')),
            oldData = fetch('hiker://files/libs/' + md5(url) + '.js'),
            remoteData = '';
        try {
            remoteData = fetchCache(url, interval, {
                headers:{
                    'User-Agent' : ua || MOBILE_UA
                },
                timeout: 50000
            });
        } catch (e) {}
        if (!remoteData.includes('http') || remoteData.includes('<body>')) { 
            log('更新失败');
            if (oldData) writeFile('hiker://files/libs/' + md5(url) + '.js', oldData);
            m3u = oldData;
        } else {
            m3u = remoteData;
        }
    }

    let mode =  m3u.indexOf('#EXTM3U') == 0 , re;
    if(mode){
        re = /(.*),(.*)\s*?((?:http|rtmp)[^#\s]*)/g;
    }else{
        re = /()(?:\B\$c_start|\B#{1,2})?(.*?),?(##|头#|\$c_end|,?#genre#|(?:http|rtmp|magnet)[^\s]*)/g;
    }

    let items = {},
        group = '未分组';
    for (let i = re.exec(m3u); i != null; i = re.exec(m3u)) {
        if (mode) {
            group = (i[1].match(/group-title="(.*?)"/) || [null, group])[1];
            ref = (i[1].match(/tvg-logo="(.*?)"/) || [null, group])[1];
        } else if (['#genre#','##','头#','$c_end'].includes(i[3])) {
            group = i[2];
            continue;
        }
        let title = i[2],
            url = i[3].includes('#') ? i[3].split('#') : [i[3].split(',')[0]]
           ref = (i[1].match(/tvg-logo="(.*?)"/) || [null, i[3].split(',')[1] ? i[3].split(',')[1] : ''])[1] 
            headers = [];
        if(!url[url.length-1]) url.pop();
        url.forEach((v,index,array)=>{
            if(/;\{(.*)\}/.test(v)){
                let obj = {},
                     con = v.match(/;\{(.*)\}/)[1],
                     arr = con.split('&&');
                arr.forEach((i)=>{
                    let [key,value] = i.split('@');
                    obj[key] = value.replace(/;/g,'；；');
                })
                array[index] = v.match(/^([^;]*);\{/)[1]
                headers.push(obj);
            }else{
                headers.push({'User-Agent' : MOBILE_UA.replace(/;/g,'；；')});
            }
            array[index] = array[index].replace(/;/g,'；；');
        });
        if (items[group]) {
            if (items[group][title]) {
                items[group][title].img = items[group][title].img;
                items[group][title].url = items[group][title].url.concat(url);
                items[group][title].headers = items[group][title].headers.concat(headers);
            } else {
                items[group][title] = {ref:ref,url:url,headers:headers};
            }
        } else {
            items[group] = {};
            items[group][title] = {ref:ref,url:url,headers:headers};
        };
    }
    return items;
}

$.exports = {
    renderLiveData: renderLiveData
}

function renderSetting() {
    function getColoredText(text) {
        return '““””<span style="color: #19B89D">' + text + '</span>'
    }
    const d = []

    var file = new java.io.File(getPath("hiker://files/tu/pic/").replace('file:/', ''));
    try{
    var fileList = file.listFiles().filter(h=>h.isFile() && /\.(jpg|jpeg|png|gif|webp)$/.test(h));
      }catch{
    var fileList = ["https://img.vinua.cn/images/zTPLb.webp"]
}

    var i = Math.floor(Math.random() * fileList.length);
    var img = fileList[i];
    d.push({
        title: "",
        col_type: "card_pic_1",
        desc: "0",
        pic_url: img,
        url: $("hiker://empty#noLoading#").rule(() => {

        })
    })

    let interval = getItem('interval', '24')
    d.push({
        title:
            interval == -1
                ? '已禁止自动更新'.fontcolor('#19B89D').bold()
                : ('更新间隔:' + interval + '小时').fontcolor('#19B89D').bold(),
        url: $(interval, '输入n为正整数时，每隔n小时自动更新\n为0时，每次打开都会更新\n为-1时，禁止自动更新').input(
            () => {
                if (parseInt(input) >= -1) {
                    setItem('interval', input)
                }
                refreshPage()
                return 'hiker://empty'
            }
        ),
        pic_url: 'https://thumbsnap.com/i/JrinF33j.jpg',
        col_type: 'avatar',
    })

    d.push({
        col_type: 'big_blank_block',
    })

    d.push({
        title: getColoredText('新建订阅'),
        col_type: 'scroll_button',
        desc: '请输入直播源订阅地址',
        url: $('', '请输入订阅地址\n可以在地址后加ua\n(使用$$$分割)').input((rule) => {
            if (input == '') {
                return 'toast://不能为空'
            } else if (input.indexOf('http') != 0 && input.indexOf('file') != 0 && input.indexOf('hiker') != 0) {
                return 'toast://链接格式有误'
            } else {
                let [url, ua] = input.split('$$$')
                return $('', '请输入订阅标题').input(
                    (url, rule, ua) => {
                        eval(JSON.parse(request('hiker://page/config?rule=' + rule)).rule)
                        let config = getConfig()
                        config.data.push({
                            name: input,
                            url: url,
                            ua: ua || '',
                        })
                        writeFile('hiker://files/rules/ApolloImg/config.json', JSON.stringify(config))
                        refreshPage()
                        return 'toast://已保存'
                    },
                    url,
                    rule,
                    ua
                )
            }
        }, getMyVar('title')),
    })

    d.push({
        title: getColoredText('导入订阅'),
        col_type: 'scroll_button',
        url: $('', '支持原始数据和云剪贴板分享链接').input((rule) => {
            eval(JSON.parse(request('hiker://page/batchIm?rule=' + rule)).rule)
            if (input.startsWith('聚图库分享##')) {
                input = parsePaste(input.split('##\n')[1])
            }
            return batchImport(input, rule)
        }, getMyVar('title')),
    })
    d.push({
        title: getColoredText('导入本地源'),
        col_type: 'scroll_button',
        desc: '请输入直播源名称',
        url: $('', '请输入直播源名称').input((rule) => {
            if (input == '') {
                return 'toast://不能为空'
            } else {
                return (
                    'fileSelect://' +
                    $.toString((name) => {
                        let s = input.split('/')
                        var url = 'hiker://files/rules/ApolloImg/' + name + '.m3u'
                        var c = fetch('hiker://files/cache/' + s[s.length - 1])
                        if (!c.includes('http')) {
                            return 'toast://非法文件'
                        }
                        writeFile(url, c)
                        eval(JSON.parse(request('hiker://page/config?rule=聚图库')).rule)
                        let config = getConfig()
                        config.data.push({
                            name: name,
                            url: url,
                        })
                        writeFile('hiker://files/rules/ApolloImg/config.json', JSON.stringify(config))
                        refreshPage()
                        return 'toast://已保存'
                    }, input)
                )
            }
        }),
    })
    d.push({
        title: getColoredText('分享订阅'),
        col_type: 'scroll_button',
        url: $(['原始数据', '云剪贴板', '云口令'], 3).select(() => {
            return $('确定导出？\n(禁用订阅不会导出)').confirm((type) => {
                eval(JSON.parse(request('hiker://page/config')).rule)
                config = getConfig()
                config.data = config.data.filter((v) => !v.inVisible)
                if (type == '云剪贴板') {
                    var data = '聚图库分享##\n' + sharePaste(JSON.stringify(config))
                } else if (type == '云口令') {
                    var data =
                        '聚图库分享,复制后打开软件即可导入\n' +
                        sharePaste(JSON.stringify(config)) +
                        '@import=js:eval(JSON.parse(fetch("hiker://page/cloud?rule=聚图库")).rule)'
                } else {
                    var data = JSON.stringify(config)
                }
                return 'copy://' + data
            }, input)
        }),
    })
    d.push({
        title: getColoredText('编辑全部'),
        col_type: 'scroll_button',
        url: 'editFile://hiker://files/rules/ApolloImg/config.json',
    })

    d.push({
        col_type: 'blank_block',
    })

    eval(JSON.parse(request('hiker://page/config')).rule)
    config = getConfig()
    let editMode = getMyVar('editMode', '启用禁用')
    ;['启用禁用', '删除订阅', '重新排序', '编辑订阅', '清除缓存'].forEach((v) => {
        d.push({
            title: v == editMode ? '““””' + v.bold().fontcolor('#19B89D') : v,
            url:
                v == editMode
                    ? 'hiker://empty'
                    : $('#noLoading#').lazyRule((v) => {
                          putMyVar('editMode', v)
                          refreshPage(false)
                          return 'hiker://empty'
                      }, v),
            col_type: 'scroll_button',
        })
    })
    config.data.forEach((v, i) => {
        let el = {
            title: v.name,
            col_type: 'text_2',
        }
        switch (editMode) {
            case '启用禁用':
                el.title = (v.inVisible ? '🔴 ' : '🟢 ') + el.title
                el.url = $('#noLoading#').lazyRule((i) => {
                    eval(JSON.parse(request('hiker://page/config')).rule)
                    config = getConfig()
                    config.data[i].inVisible = !config.data[i].inVisible
                    writeFile('hiker://files/rules/ApolloImg/config.json', JSON.stringify(config))
                    refreshPage(false)
                    return 'hiker://empty'
                }, i)
                break
            case '删除订阅':
                el.url =
                    'confirm://确认删除“' +
                    v.name +
                    '”订阅？.js:' +
                    $.toString((i) => {
                        eval(JSON.parse(request('hiker://page/config')).rule)
                        config = getConfig()
                        config.data.splice(i, 1)
                        writeFile('hiker://files/rules/ApolloImg/config.json', JSON.stringify(config))
                        refreshPage(false)
                        return 'toast://已删除'
                    }, i)
                break
            case '重新排序':
                let sortFlag = parseInt(getMyVar('sortFlag', '-1'))
                el.title = (sortFlag == i ? '🔃  ' : '') + el.title
                if (sortFlag == -1)
                    el.url = $('#noLoading#').lazyRule((i) => {
                        putMyVar('sortFlag', i.toString())
                        refreshPage(false)
                        return 'toast://选择要移动到的位置'
                    }, i)
                else
                    el.url = $('#noLoading#').lazyRule(
                        (oldIndex, newIndex) => {
                            eval(JSON.parse(request('hiker://page/config')).rule)
                            config = getConfig()
                            config.data.splice(newIndex, 0, config.data.splice(oldIndex, 1)[0])
                            writeFile('hiker://files/rules/ApolloImg/config.json', JSON.stringify(config))
                            putMyVar('sortFlag', '-1')
                            refreshPage(false)
                            return 'hiker://empty'
                        },
                        sortFlag,
                        i
                    )
                break
            case '编辑订阅':
                let arr = ['编辑名称', '编辑地址', '编辑内容', '选择样式']
                el.url = $(arr, 3).select(
                    (v, i) => {
                        if (input == '编辑名称') {
                            return $(v.name, '输入新名称').input((i) => {
                                eval(JSON.parse(request('hiker://page/config')).rule)
                                config = getConfig()
                                if (input) {
                                    config.data[i].name = input
                                    writeFile('hiker://files/rules/ApolloImg/config.json', JSON.stringify(config))
                                    refreshPage(false)
                                    return 'toast://修改成功'
                                } else {
                                    return 'toast://不能为空'
                                }
                            }, i)
                        } else if (input == '编辑地址') {
                            return $(v.ua ? v.url + '$$$' + v.ua : v.url, '输入新地址').input((i) => {
                                eval(JSON.parse(request('hiker://page/config')).rule)
                                config = getConfig()
                                if (input == '') {
                                    return 'toast://不能为空'
                                } else if (
                                    input.indexOf('http') != 0 &&
                                    input.indexOf('file') != 0 &&
                                    input.indexOf('hiker') != 0
                                ) {
                                    return 'toast://链接格式有误'
                                } else {
                                    let [url, ua] = input.split('$$$')
                                    config.data[i].url = url
                                    config.data[i].ua = ua
                                    writeFile('hiker://files/rules/ApolloImg/config.json', JSON.stringify(config))
                                    refreshPage(false)
                                    return 'toast://修改成功'
                                }
                            }, i)
                        } else if (input == '编辑内容') {
                            if (v.url.startsWith('file://') || v.url.startsWith('hiker://files')) {
                                return 'editFile://' + v.url
                            }
                            return 'editFile://hiker://files/libs/' + md5(v.url) + '.js'
                        } else if (input == '选择样式') {
                            return $(["movie_2","movie_3","pic_1","pic_1_full","pic_1_card","pic_2","pic_2_card","pic_3","pic_3_square","icon_2","icon_2_round","icon_small_3","icon_3_fill","icon_3_round_fill","icon_4","icon_4_card","icon_small_4","icon_round_4","icon_round_small_4","icon_5","card_pic_1","card_pic_2","card_pic_2_2","card_pic_2_2_left","card_pic_3","card_pic_3_center","pic_1_center","text_1","text_2","text_3","text_4","text_5","text_center_1","text_icon","avatar"], 2, '请选择').select((v) => {
                                setItem(v.name, input)
                            },v)
                        }
                    },
                    v,
                    i
                )
                break
            case '清除缓存':
                el.url = $('确定清除“' + v.name + '”订阅缓存？\n(可立即更新)').confirm((url) => {
                    deleteCache(url)
                    return 'toast://清除成功'
                }, v.url)
                break
        }
        d.push(el)
    })
    return d
}

$.exports = {
    renderSetting: renderSetting,
}

