var d = [];

var CW_OK = 'post-card-container';
var POOL = ["https://51cg1.icu/", "https://51cg1.art/", "https://51cg1.click/", "https://51cg1.shop/", "https://chigua.art/", "https://chigua1.art/", "https://chigua1.click/", "https://chigua1.one/", "https://chigua3.top/", "https://chigua6.top/", "https://51cg4.wiki/", "https://51cg5.wiki/", "https://51cg7.wiki/", "https://51cg8.wiki/", "https://51cg10.wiki/", "https://chigua4.wiki/", "https://chigua5.wiki/", "https://chigua9.wiki/", "https://chigua10.wiki/", "https://chigua.com/", "https://51cg1.com/"];

function cgOk(t) {
    return !!t && t.length > 20000 && t.indexOf(CW_OK) > -1 && t.indexOf('吃瓜') > -1;
}
function cgProbe(u) {
    try {
        if (u.slice(-1) != '/') u = u + '/';
        if (cgOk(fetch(u + 'page/2/', { timeout: 7000 }))) return true;
        if (cgOk(fetch(u, { timeout: 7000 }))) return true;
    } catch (e) {}
    return false;
}
function cgExtra() {
    try { return JSON.parse(getItem('cg51_extra', '[]')) || []; } catch (e) { return []; }
}
function cgDiscover(html, host) {
    try {
        var ms = html.match(/https?:\/\/[a-z0-9\-]+(?:\.[a-z0-9\-]+)*\.[a-z]{2,6}\//gi) || [];
        var ex = cgExtra();
        var bad = /cloudfront|google|yandex|gstatic|w3\.org|schema|mozilla|jquery|bootstrap|jsdelivr|51cg|chigua|51hlw|baoyang|iwangzi|huanggua|doubleclick|ads\.|cdn\./i;
        for (var i = 0; i < ms.length && ex.length < 4; i++) {
            var u = ms[i];
            if (bad.test(u)) continue;
            if (ex.indexOf(u) > -1) continue;
            if (cgProbe(u)) ex.push(u);
        }
        if (ex.length) setItem('cg51_extra', JSON.stringify(ex));
    } catch (e) {}
}
function cgHost(force) {
    var dt = new Date();
    var day = '' + dt.getFullYear() + (dt.getMonth() + 1) + dt.getDate();
    var cached = getItem('cg51_host', '');
    if (cached && !force && getItem('cg51_day', '') == day) return cached;
    if (cached && cgProbe(cached)) { setItem('cg51_day', day); return cached; }
    var cand = cgExtra().concat(POOL);
    for (var i = 0; i < cand.length; i++) {
        if (cgProbe(cand[i])) {
            var nh = cand[i];
            setItem('cg51_host', nh);
            setItem('cg51_day', day);
            if (cached != nh) toast('线路已切换：' + nh.replace('https://', '').replace(/\/$/, ''));
            return nh;
        }
    }
    if (cached) return cached;
    return POOL[0];
}
function cgImg(it, host) {
    var img = pdfh(it, '.post-card&&data-banner') || '';
    if (!img) img = pdfh(it, 'div&&data-banner') || pdfh(it, 'a&&data-banner') || '';
    if (!img) {
        var sc = pdfh(it, 'script&&Html') || '';
        var ix = sc.indexOf('loadBannerDirect');
        if (ix > -1) {
            var mm = sc.slice(ix + 17).split("'");
            if (mm.length > 1) img = mm[0];
        }
    }
    if (img && img.indexOf('http') != 0) img = host + img.replace(/^\//, '');
    return img;
}
function cgList(html, host, d) {
    var list = pdfa(html, 'body&&article');
    for (var j in list) {
        var it = list[j];
        var t = pdfh(it, 'h2.post-card-title&&Text') || pdfh(it, '.post-card-title&&Text') || '';
        t = t.replace(/\s+/g, ' ').replace(/\s*(热搜 HOT|置顶|推荐|热榜|广告)\s*$/g, '').trim();
        if (!t) continue;
        var href = pdfh(it, 'meta[itemprop="url mainEntityOfPage"]&&content') || '';
        if (!href) href = pd(it, 'a&&href') || '';
        if (!href || !/archives/.test(href)) continue;
        if (href.indexOf('http') != 0) href = host + href.replace(/^\//, '');
        var date = pdfh(it, 'span[itemprop="datePublished"]&&content') || pdfh(it, 'meta[itemprop="dateModified"]&&content') || '';
        var info = pdfh(it, '.post-card-info&&Text') || '';
        var dm = info.match(/\d+\s*年\s*\d+\s*月\s*\d+\s*日/);
        var tag = '';
        var sp = info.match(/•\s*([^•]{2,20})\s*$/);
        if (sp) tag = sp[1].replace(/\s+/g, ' ').trim();
        var desc = (date ? '🗓 ' + date.replace(/\s+/g, ' ').trim() : (dm ? dm[0] : ''));
        if (tag) desc = (desc ? desc + '　' : '') + '🏷 ' + tag;
        d.push({
            title: t,
            img: cgImg(it, host),
            desc: desc,
            url: href + '@rule=js:$.require("hiker://page/erji")',
            col_type: 'movie_2'
        });
    }
    return d;
}

var host = cgHost(false);
if (host.slice(-1) != '/') host = host + '/';

if (MY_PAGE == 1) {
    d.push({
        title: '🔍',
        url: $.toString((r) => {
            putMyVar('keyword', input);
            return 'hiker://search?rule=' + r + '&s=' + input;
        }, MY_RULE.title),
        col_type: 'search'
    });
    d.push({ title: '当前线路：' + host.replace('https://', '').replace(/\/$/, ''), col_type: 'text_center_1' });
    d.push({ col_type: 'line' });
}

var url = MY_URL.replace('hiker://empty##', host);
var html = fetch(url, { timeout: 20000 }) || '';
if (html.length < 5000) {
    host = cgHost(true);
    if (host.slice(-1) != '/') host = host + '/';
    url = MY_URL.replace('hiker://empty##', host);
    cgDiscover(html, host);
    html = fetch(url, { timeout: 20000 }) || '';
}
if (html.length < 5000) toast('暂时取不到数据，退出重进会自动换线');

cgList(html, host, d);
if (d.length <= 3) toast('这页没解析出内容，退出重进会自动换线');
setResult(d);

