var lazy = $('').lazyRule((tag) => {
  var html = fetchPC(input);
  var contents = pdfa(html, 'body&&.paginator&&a');
  var content = contents.map(x => pdfh(x, 'a&&Text'));
  var num = content[content.length-2] ? content[content.length-2] : "1";
  var allPics = [];
  var page = [];
  for (var i = 1; i <= num; i++) {
    page.push({
      url: input.replace("index", "index-page-" + i),
      options: { headers: {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/105.0.0.0 Safari/537.36"
      }}
    });
  }
  //log(page)
  var timg = tag<4?"img1":"img5"
  var pics = batchFetch(page).map(function(item) {
    var list = pdfa(item, "body&&.gallary_item");
    return list.map(function(listItem) {
      var name = pdfh(listItem, ".name&&Text");
      return pd(listItem, "img&&src")
        .replace(/t\d/, timg)
        .replace('data/t', 'data')
        .replace(/[^/]+(?=\.jpg|.png$)/, name);
    });
  }).flat();
  //log(pics);
  return "pics://" + pics.join("&&");
},tag);

