                            for (var i in urls) {
                                if (urls[i].match(/dycdn\-tos\.pstatp|\.m3u8|\.mp4|\.flv|netease\.com|video_mp4|type\=m3u8|pt\=m3u8|\/video\/tos\//) && !urls[i].match(/\.html|m3u8\.tv|m3u8\.pw|\&next|ac\=dm|\=http|https\:\/\/[\d]\.m3u8|\?url\=\/m3u8|\.css|\.js\?/)) {
                                    //fy_bridge_app.log(urls[i])
                                    if (fy_bridge_app.getHeaderUrl) {
                                        return fy_bridge_app.getHeaderUrl(urls[i]).replace(";{", "#ignoreImg=true##isVideo=true#;{");
                                    } else {
                                        return urls[i] + '#isVideo=true#'
                                    }
                                }
                            } //end for i
                        }
                    }
                },
                srcurl);
            return video
        }

        return x5rule(currentUrl, currentUrl);
        //return playUrl + ";{Referer@" + currentUrl + "}"

    } else if (/d0000d|dood|ds2play|vidply|do7go|all3do/.test(location)) {

        //④DS线路
        var html = fetchCodeByWebView(location, {
            headers: {
                'Referer': referer
            }
        })
        var pass_md5 = getHome(location) + html.match(/\/pass_md5[^"']+/)[0]
        var token = html.match(/cookieIndex.*?\'(.*?)\'/)[1]
        var data = fetch(pass_md5, {
            headers: {
                "Referer": location
            }
        })

        function makePlay(token) {
            for (var a = "",
                    t = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789",
                    n = t.length,
                    o = 0; 10 > o; o++)
                a += t.charAt(Math.floor(Math.random() * n));
            return a + "?token=" + token + "&expiry=" + Date.now();
        };
        var playUrl = data + makePlay(token)
        return playUrl + "#isVideo=true#;{Referer@" + location + "}"

    } else if (location.includes("vtbe.to")) {

        //⑤VTU线路
        function evaldecode(text) {
            var code = '';
            var s = text.replace(/^eval/, '')
                .replace('return p', 'code+=p')
            eval(s);
            return code;
        }
        var hostRegex = (url) => {
            var match = url.match(/^(?:https?:\/\/)?(?:www\.)?([a-zA-Z0-9-]{1,63}\.)+[a-zA-Z]{2,6}/i);
            return match ? match[0] : url;
        };
        let host = hostRegex(referer)
        var html = fetch(location, {
            headers: {
                Referer: host,
            }
        })
        var iframe = pdfa(html, "iframe");
        if (iframe.length > 0) {
            html = fetch(pdfh(iframe[0], "iframe&&src"), {
                headers: {
                    Referer: host,
                }
            })
        }
        var scripts = pdfa(html, "body&&script");
        let script = scripts.filter(x => x.includes('eval')).map(m => pdfh(m, "script&&Html"))[0];
        if (script == undefined) {
            return 'toast://无数据'
        }
        let m3u8 = /file:"(.*?)"/g.exec(evaldecode(script))[1];
        return m3u8;

    } else {
        log("革命尚未成功,同志仍需努力!")
        return "confirm://咳,本线路这个地址并没有解析，日志已打印出，敬请查看.js:'hiker://empty' "
    }
})

