// 获取当前时间，生成版本号
function time_to_version() {
    let now = new Date()
    let year = now.getFullYear()
    let month = (now.getMonth() + 1).toString().padStart(2, '0')
    let day = now.getDate().toString().padStart(2, '0')
    let hour = now.getHours().toString().padStart(2, '0')
    let minute = now.getMinutes().toString().padStart(2, '0')
    let second = now.getSeconds().toString().padStart(2, '0')
    let formattedTime = `${year}${month}${day}${hour}${minute}${second}`
    return formattedTime
}

// 自动更新检测
function auto_update() {
    try {
        let update_url = 'https://textdb.online/LoveBG'
        let update_info = fetch(update_url)
        update_info = JSON.parse(update_info)
        let current_version = MY_RULE.version
        if (Number(current_version) < Number(update_info.version)) {
            confirm({
                title: '更新提示',
                content: update_info.content ? update_info.content : ' ',
                confirm: () => {
                    showLoading('正在更新本小程序')
                    let update_url = 'https://textdb.online/LoveBG'
                    let update_info_2 = fetch(update_url)
                    update_info_2 = JSON.parse(update_info_2)
                    let MY_RULE_new = parsePaste(update_info_2.url)
                    hideLoading()
                    return MY_RULE_new
                },
                cancel: () => {
                    return 'toast://你将无法使用本程序的最新功能'
                },
            })
        } else {
            return 'latest'
        }
    } catch (e) {
        toast('GG，更新失效了！')
    }
}

// 去除提交更新信息方法，再上传云剪贴板，返回最新版本的小程序云口令
function submit_latest_rule() {
    // 先获取原规则内容
    let submit_update_origin_my_rule = MY_RULE

    // 正则命中上传更新方法内容
    let submit_update_info_code_regex = /submit_update_info\(.*?\)/g

    // json规则转字符串规则,然后正则替换删除所有上传更新方法内容
    let submit_update_replace_my_rule = JSON.stringify(submit_update_origin_my_rule).replace(
        submit_update_info_code_regex,
        ''
    )

    // 构造上传的最终规则内容
    let submit_update_my_rule =
        `海阔视界规则分享，当前分享的是：小程序￥home_rule_v2￥base64://@${MY_RULE.title}@` +
        base64Encode(submit_update_replace_my_rule)

    // 上传内容到剪贴板
    let update_info_url = fetch('https://pasteme.tyrantg.com/api/create', {
        body: {
            lang: 'plain',
            content: submit_update_my_rule
        },
    })
    update_info_url = JSON.parse(update_info_url)
    update_info_url = '云6oooole/xxxxxx/' + update_info_url.data.path
    // 复制和返回云剪贴板地址
    copy('update_info_url')
    return update_info_url
}

// 提交更新信息
function submit_update_info(flag, content, ad) {
    if (flag) {
        let update_info = {
            version: MY_RULE.version,
            ad: ad ? ad : '',
            content: content ? content : '',
            url: submit_latest_rule().split('\n')[0],
        }
        let s_value = JSON.stringify(update_info)
        let s_res = post('https://api.textdb.online/update/', {
            body: {
                key: 'LoveBG',
                value: s_value
            }
        })
        try {
            JSON.parse(s_res)
            copy('https://textdb.online/LoveBG')
        } catch {
            toast('提交更新信息失败')
        }
    }
}

$.exports = {
    submit_update_info,
    auto_update,
}

// 每日一句API，写入缓存(每日一句、时间)，返回每日一句
function save_day_say_cache() {
    let day_say_cache = {}
    let day_say_html = fetch('https://v1.hitokoto.cn', {
        headers: {
            'User-Agent':
                'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36',
        },
    })
    day_say_html = JSON.parse(day_say_html)
    // 缓存获取内容和时间到day_say_cache
    day_say_cache['content'] = day_say_html['hitokoto']
    day_say_cache['time'] = Math.floor(Date.now() / 1000)
    globalMap0.putMyVar('daysay', day_say_cache)
    // 返回获取内容
    return day_say_html['hitokoto']
}

// 生成带每日一句的搜索框
function generate_day_say_input(res, interval) {
    let day_say = ''
    let interval_time = interval ? interval : 10
    try {
        let day_say_cache = {}
        let day_time = 0
        if (globalMap0.hasMyVar('daysay')) {
            day_say_cache = globalMap0.getMyVar('daysay', {})
            day_time = day_say_cache['time']
            // 超时
            if (Math.floor(Date.now() / 1000) - day_time >= interval_time) {
                day_say = save_day_say_cache()
            } else {
                day_say = day_say_cache['content']
            }
        } else {
            day_say = save_day_say_cache()
        }
    } catch {
        day_say = ''
    }

    res.push({
        title: '搜索',
        col_type: 'input',
        desc: ' 😍：' + day_say,
        url: "'hiker://search?s=' + input + '&rule='+MY_RULE.title",
    })
}

$.exports = {
    generate_day_say_input,
}

