      var url = html.url
      if (html.encrypt == '1') {
        url = unescape(url);
      } else if (html.encrypt == '2') {
        url = unescape(base64Decode(url));
      }
      if (/m3u8|mp4/.test(url)) {
        return url
      } else {
        return "video://" + input
      }
    } catch (e) {
      return "video://" + input
    }
  }),
  evalJSRule: function (item, jsRule) {
    let rule = jsRule.replace("@js:", "");
    rule = rule.trim();
    //log($.stringify(rule))
    let input = item;
    if (rule.startsWith("(")) {
      eval("result = " + rule);
    } else {
      /**
      * 还原成 $.toString(...) 的最终结果，达到最终处理方式跟上面的 if 一致的目的
      */
      eval("result = " + "(() => {" + rule + "})()");
    }
    return result || "";
  },
