function dynamicClass(options) {
    const obj = {
        //默认值
        layout: "undefined",
        html: "empty",
        page: 0,
        分类颜色: "#FA7298",
        折叠: "““””<b>" + "∧".fontcolor("#1aad19") + "</b>",
        展开: "““””<b>" + "∨".fontcolor("#FF0000") + "</b>",
        open: true,
        state: MY_RULE.url,
        search: false,
        clears: [],
        clearall: ["yi_firstpage"],
        debug: false,

        预设(param) {
            if (param == undefined) {
                param = [];
            }
            Object.keys(param).forEach((property) => {
                // 对每个属性名执行操作
                const value = param[property]; // 获取属性值
                // 在这里执行您的操作
                this[property] = value;
                if (this.debug) {
                    console.log(property + ":" + value);
                }
            });
        },
        evalJSRule(item,
            jsRule) {
            let rule = jsRule.replace("@js:",
                "");
            rule = rule.trim();
